ns.setBonus = {
    { en = "$?a1259297[$@spellaura1259297][Every $proccooldown seconds during combat, you capitalize on your next critical strike to gain the Upper Hand. Every situation is different, as is your Upper Hand at the time. Healing tonics, poisoned daggers, and other magical contraband are all on the table.]", ua = "$?a1259297[$@spellaura1259297][Кожні $proccooldown секунд у бою ви користаєтеся своїм наступним критичним ударом, щоб здобути Перевагу. Кожна ситуація інша, як і ваша Перевага цієї миті. Зцілювальні тоніки, отруєні кинджали та інша магічна контрабанда — усе доступне.]" },
    { en = "$?a455524[|cnRED_FONT_COLOR:Modified by Cool Sunset Bracers.|r\n\nHealing spells and abilities have the chance to cause your tailored threads to radiate with Woven Duskweave granting $s2 Haste for $457630d.][$@spelldesc455522]", ua = "$?a455524[|cnRED_FONT_COLOR:Змінено Наручами прохолодного заходу сонця.|r\n\nЗцілювальні закляття та здібності мають шанс змусити ваші виткані нитки засяяти Тканим сутінковим плетивом, надаючи $s2 Поспіху протягом $457630d.][$@spelldesc455522]" },
    { en = "$?a457629[|cnRED_FONT_COLOR:Modified by Warm Sunrise Bracers.|r\n\nDamaging spells and abilities have the chance to cause your tailored threads to radiate with Woven Dawnweave granting $s2 Mastery for $457627d.][$@spelldesc457630]", ua = "$?a457629[|cnRED_FONT_COLOR:Змінено Наручами теплого світанку.|r\n\nЗакляття та здібності, що завдають шкоди, мають шанс змусити ваші виткані нитки засяяти Тканим світанковим плетивом, надаючи $s2 Майстерності протягом $457627d.][$@spelldesc457630]" },
    { en = "$?s102543[Incarnation: Avatar of Ashamane][Berserk] lasts ${$s1/1000} sec longer.", ua = "$?s102543[Втілення: Аватар Ашамані][Берсерк] триває на ${$s1/1000} сек. довше." },
    { en = "$?s117014[Elemental Blast][Earth Shock] damage increased by $s1%. Earthquake damage increased by $s2%.", ua = "Шкода від $?s117014[«Стихійного вибуху»][«Земного шоку»] збільшена на $s1%. Шкода від «Землетрусу» збільшена на $s2%." },
    { en = "$?s152173[Serenity][Storm, Earth, and Fire] grants you $181744m1% damage reduction for $181744d.", ua = "$?s152173[«Незворушність»][«Буря, земля і вогонь»] дарує вам $181744m1% зниження шкоди протягом $181744d." },
