    { en = "$?s259387[Mongoose Bite][Raptor Strike], Carve, and Butchery damage increased by $s1%.", ua = "Шкоду $?s259387[«Укусу мангуста»][«Удару раптора»], «Розтину» та «Різанини» збільшено на $s1%." },
