    { en = "$?s262161[Warbreaker][Colossus Smash] lasts ${$s1/1000} sec longer and increases your damage dealt to affected enemies by an additional $s2%.", ua = "$?s262161[«Зброя війни»][«Колосальний удар»] триває на ${$s1/1000} сек довше та збільшує шкоду, яку ви завдаєте ураженим ворогам, на додаткові $s2%." },
    { en = "$?s263642[Fracture][Shear] deals $s1% more damage, generates $s2% more Fury, and has a 15% chance to generate an additional Soul Fragment.", ua = "$?s263642[«Перелом»][«Розсічення»] завдає на $s1% більше шкоди, генерує на $s2% більше Гніву і має 15% шанс згенерувати додатковий фрагмент душі." },
