    { en = "Cobra Shot, Kill Command, and Multi-Shot reduce the cooldown of Bestial Wrath by ${$m1/1000}.1 sec.", ua = "«Постріл кобри», «Наказ убити» та «Багатоцільовий постріл» зменшують час відновлення «Звірячого гніву» на ${$m1/1000}.1 с." },
    { en = "Cobra Shot, Multi-Shot, and Kill Command deal $246116s1% increased damage while Bestial Wrath is active.", ua = "Постріл кобри, Множинний постріл та Наказ убити завдають на $246116s1% більше шкоди, поки активний Звіриний гнів." },
    { en = "Cobra Shot, Multi-shot, and Kill Command increase the damage bonus of Bestial Wrath by ${$246126s1/10}.1% for its remaining duration.", ua = "«Постріл кобри», «Багатоцільовий постріл» та «Наказ убити» збільшують бонус до шкоди «Звірячого гніву» на ${$246126s1/10}.1% на решту його тривалості." },
    { en = "Collapsing Star damage increased by $s1% and it now generates $1271663s1 Fury.", ua = "Шкода Колапсуючої Зорі підвищена на $s1%, і вона тепер створює $1271663s1 Гніву." },
