    { en = "Conflagrate gains an additional charge and has ${$m2/-1000} sec reduced cooldown.", ua = "Займання отримує додатковий заряд, а його час відновлення зменшено на ${$m2/-1000} с." },
    { en = "Conflagrate generates $s1 additional Soul Shard fragments and its damage is increased by $s2%.", ua = "«Займання» генерує $s1 додаткових уламків Осколка душі, а його шкода підвищується на $s2%." },
    { en = "Consecration increases the effect of Shield of the Righteous and Light of the Protector by an additional $s1%.", ua = "«Освячення землі» збільшує ефект «Щита праведних» та «Світла захисника» на додаткові $s1%." },
    { en = "Consecration is $s1% larger and enemies within your Consecration are illuminated, increasing the chance for your abilities to critically strike them by $s2%.", ua = "Освячення на $s1% більше, а вороги всередині вашого Освячення осяяні, що збільшує шанс ваших здібностей завдати їм критичного удару на $s2%." },
    { en = "Consuming $s1 rage grants a stack of Seeing Red, which transforms at $364006u stacks into Outburst, causing your next Shield Slam or Thunder Clap to be $364010s1% more effective and grant Ignore Pain.", ua = "Витрачання $s1 гніву дарує заряд Червоної пелени, що при $364006u зарядах перетворюється на Спалах люті, роблячи ваш наступний Удар щитом чи Громовий удар на $364010s1% ефективнішим і даруючи Нехтування болем." },
    { en = "Consuming Clearcasting grants increased spell damage by $424293s1% for $424293d, stacking up to ${$424293u*$s1}%.", ua = "Витрачання «Ясного чаклування» дає збільшену на $424293s1% шкоду заклять на $424293d, накопичуючись до ${$424293u*$s1}%." },
    { en = "Consuming Clearcasting now causes your Regrowth to also cast Nourish onto a nearby injured ally at $s1% effectiveness, preferring those with your heal over time effects.", ua = "Витрата «Ясного розуму» тепер змушує ваше «Відродження» також застосовувати «Живлення» на ближнього пораненого союзника з $s1% ефективністю, надаючи перевагу тим, на кому є ваші ефекти поступового зцілення." },
