    { en = "Consuming Essence Burst sends forth a Living Flame at your target at $s1% effectiveness, or a nearby injured target if they are full health.", ua = "Поглинання Спалаху есенції посилає Живе полум'я на вашу ціль з $s1% ефективністю або на поранену ціль поблизу, якщо ваша ціль має повне здоров'я." },
    { en = "Consuming Fingers of Frost increases spell damage by $394994s1% for $394994d.", ua = "Використання «Крижаних пальців» підвищує шкоду закляттями на $394994s1% на $394994d." },
    { en = "Consuming Glacial Spike has a small chance to grant Glacial Spike. Shatter damage increased by $s1%.", ua = "Поглинання Льодовикового шпиля має невеликий шанс надати Льодовиковий шпиль. Шкода від Розтрощення збільшена на $s1%." },
    { en = "Consuming Killing Machine fires a Glacial Advance through your target.", ua = "Використання «Машини вбивства» випускає «Льодовиковий наступ» крізь вашу ціль." },
    { en = "Consuming Lock and Load also fires an Explosive Shot at $s1% effectiveness.", ua = "Поглинання «Заряджай і пали» також випускає «Вибуховий постріл» з $s1% ефективністю." },
