    { en = "Consuming a Soul Fragment increases the damage and healing of your next Fel Devastation by $454774s1%, up to ${$454774s1*$454774u}%.", ua = "Поглинання фрагмента душі збільшує шкоду та зцілення вашого наступного «Спустошення Скверни» на $454774s1%, до ${$454774s1*$454774u}%." },
    { en = "Consuming a brew has a $h% chance to generate a Gift of the Ox Healing Sphere.", ua = "Вживання варива має $h% шанс згенерувати Зцілюючу сферу «Дару вола»." },
    { en = "Corruption has a chance to generate a soul shard whenever it deals damage.", ua = "«Зіпсуття» має шанс згенерувати уламок душі щоразу, коли завдає шкоди." },
    { en = "Crash Lightning increases your critical strike chance by $242284s1% for $242284d.", ua = "«Розлам блискавки» збільшує ваш шанс критичного удару на $242284s1% на $242284d." },
    { en = "Crash Lightning weapon enhancement effect additionally increases your Mastery by $s1%.", ua = "Ефект поліпшення зброї Розтрощлива блискавка додатково збільшує вашу Майстерність на $s1%." },
    { en = "Crimson Scourge increases the damage of your next Death and Decay by $s1%, and grants $1300369s1% critical strike chance for $1300369d when consumed.", ua = "Багряна погибель збільшує шкоду вашого наступного Смерті й тліну на $s1% та надає $1300369s1% шансу критичного удару протягом $1300369d при поглинанні." },
