    { en = "Death Coil and Epidemic damage increased by $s1%. Casting Death Coil or Epidemic grants a stack of Master of Death, up to $408375u. Dark Transformation consumes Master of Death and grants $408375s1% Mastery for each stack for $408376d.", ua = "Шкода «Смертельної завіси» та «Епідемії» збільшена на $s1%. Творіння «Смертельної завіси» чи «Епідемії» надає заряд «Володаря смерті», до $408375u. «Темне перетворення» витрачає «Володаря смерті» й надає $408375s1% Майстерності за кожен заряд протягом $408376d." },
    { en = "Death Coil causes the target to take an additional $s1% of the direct damage dealt over $253367d.", ua = "«Тенета смерті» змушують ціль зазнати додатково $s1% завданої прямої шкоди протягом $253367d." },
    { en = "Death Coil has a $h% chance to deal damage a second time.", ua = "«Оболонка смерті» має $h% шансу завдати шкоди вдруге." },
    { en = "Death Coil has a $s1% chance to infect the target with a Festering Wound.", ua = "«Мертвотна змійка» має $s1% шансу заразити ціль «Гнійною раною»." },
    { en = "Death Coil increases the duration of Dark Transformation by ${$m1/1000}.1 sec per cast. Special attacks while Pillar of Frost is active will impale your target with an icy spike.", ua = "«Смертельна змія» збільшує тривалість «Темного перетворення» на ${$m1/1000}.1 с за прочитання. Спеціальні атаки під час дії «Стовпа морозу» протинають вашу ціль крижаним шипом." },
    { en = "Death Strike deals $s1% increased damage has an $s2% chance to grant a charge of Blood Boil.", ua = "Смертельний удар завдає на $s1% більше шкоди і має $s2% шанс дарувати заряд Кипіння крові." },
    { en = "Death Strike has a $h% chance to generate a Rune.", ua = "Смертельний удар має $h% шанс створити Руну." },
    { en = "Death Strike reduces the cooldown of Vampiric Blood by ${$m1/-1000} sec.", ua = "Смертельний удар зменшує відновлення Вампірської крові на ${$m1/-1000} сек." },
    { en = "Decrease the energy cost of Eviscerate and Rupture by $s1.", ua = "Зменшує вартість енергії Патрання і Розриву на $s1." },
