    { en = "Each $s3 energy you spend grants Natureblight, granting ${$s1}.1% attack speed and ${$s2}.1% Nature Damage for $426568d. Multiple instances of Natureblight may overlap, up to $426568u.", ua = "Кожні витрачені $s3 енергії дають «Природну хворобу», що надає ${$s1}.1% швидкості атаки та ${$s2}.1% шкоди Природи на $426568d. Кілька примірників «Природної хвороби» можуть накладатися, до $426568u." },
    { en = "Each Arcane Charge increases your critical strike chance by ${$s1}.1%.", ua = "Кожен «Арканний заряд» збільшує ваш шанс критичного удару на ${$s1}.1%." },
    { en = "Each Arcane Charge you spend increases your damage dealt by $s1% for $253262d.", ua = "Кожен витрачений Арканний Заряд підвищує завдану вами шкоду на $s1% на $253262d." },
    { en = "Each Combo Point spent reduces the cooldown of Symbols of Death by ${$m1/10}.1 sec.", ua = "Кожне витрачене очко комбо зменшує час відновлення Символів смерті на ${$m1/10}.1 с." },
