    { en = "Each attack you dodge while Savage Defense is active increases the healing from your next Frenzied Regeneration within $138217d by $138217s1%, stacking up to $138217u times.", ua = "Кожна атака, яку ви ухиляєте, поки активний «Дикий захист», збільшує зцілення від вашого наступного «Несамовитого відновлення» протягом $138217d на $138217s1%, накопичуючись до $138217u разів." },
    { en = "Each combo point spent reduces the cooldown of $?s102543[Incarnation: King of the Jungle][Berserk] by ${$s1*0.1}.1 sec.", ua = "Кожне витрачене очко комбо зменшує час відновлення $?s102543[«Втілення: Король джунглів»][«Берсерка»] на ${$s1*0.1}.1 с." },
    { en = "Each ghoul summoned by Army of the Dead increases your damage by $246995s1% for $246995d. Duration extends and does not stack.", ua = "Кожен упир, прикликаний «Армією мертвих», збільшує вашу шкоду на $246995s1% протягом $246995d. Тривалість подовжується й не накопичується." },
    { en = "Each of the heroes summoned by Time Anomaly increases the damage you deal by $190623s1% until it departs.", ua = "Кожен герой, прикликаний «Часовою аномалією», збільшує завдану вами шкоду на $190623s1%, доки не зникне." },
    { en = "Each of your melee autoattacks has a $h% chance to activate Deadly Scheme for $90472d, increasing the critical strike chance on your next Eviscerate or Envenom by $90472s1%.", ua = "Кожна ваша автоатака ближнього бою має $h% шанс активувати «Смертельний задум» на $90472d, збільшуючи шанс критичного удару вашого наступного «Потрошіння» чи «Отруєння» на $90472s1%." },
    { en = "Each rune you spend reduces the cooldown of Army of the Dead by ${$s1/10}.1 seconds.", ua = "Кожна витрачена вами руна зменшує відновлення Армії мертвих на ${$s1/10}.1 секунди." },
