    { en = "Each stack of Freezing Shattered has a $s2% chance to generate an Icicle. Glacial Spike damage increased by $s1%.", ua = "Кожен заряд розтрощеного Замерзання має $s2% шанс створити Бурульку. Шкода від Льодовикового шпиля збільшена на $s1%." },
    { en = "Each stack of Stolen Time also reduces the base cooldown of Arcane Power, Combustion, and Icy Veins by $105791s1%.", ua = "Кожен заряд «Викраденого часу» також зменшує базове відновлення «Арканної сили», «Спалення» й «Крижаних вен» на $105791s1%." },
    { en = "Each stack of Void Form increases the critical strike chance of Mind Flay, Void Bolt, and Mind Blast by ${$252909m1/2}.1%.", ua = "Кожен стос «Форми Порожнечі» збільшує шанс критичного удару «Здирання розуму», «Стріли Порожнечі» і «Удару розуму» на ${$252909m1/2}.1%." },
    { en = "Each successive ice bolt of a cast of Flurry deals $s1% more damage.", ua = "Кожен наступний крижаний заряд застосування «Шквалу» завдає на $s1% більше шкоди." },
    { en = "Each target affected by your Renew increases your Haste by $1306118s1%, up to ${$1306118s2*$1306118u}%.", ua = "Кожна ціль, на яку діє ваше Оновлення, збільшує ваш Поспіх на $1306118s1%, до ${$1306118s2*$1306118u}%." },
    { en = "Each target hit by Light of Dawn has a $s3% chance to reduce the remaining cooldown of Avenging Wrath by $s2 sec.", ua = "Кожна ціль, вражена «Світлом світанку», має $s3% шанс зменшити залишкове відновлення «Караючого гніву» на $s2 с." },
    { en = "Each time Drain Life or Drain Soul deals damage, it has a $h% chance to make your next Unstable Affliction not consume a Soul Shard.", ua = "Щоразу, коли «Витягування життя» чи «Витягування душі» завдає шкоди, воно має $h% шанс зробити так, що ваша наступна «Нестабільна недуга» не витратить уламок душі." },
    { en = "Each time Elemental Overload triggers, you gain $105821s1 haste for $105821d, stacking up to $105821u times.", ua = "Щоразу, коли спрацьовує Стихійне перевантаження, ви отримуєте $105821s1 Поспіху на $105821d, накопичуючись до $105821u разів." },
    { en = "Each time Penance heals or damages, it has a $s1% chance to heal another injured ally near your target.", ua = "Щоразу, коли «Покаяння» зцілює чи завдає шкоди, воно має $s1% шанс зцілити іншого пораненого союзника біля вашої цілі." },
    { en = "Each time Remorseless Winter damages at least 1 enemy, gain Freezing Tempest which grants $1297365s1% attack speed and $1297365s2% increased Icy Death Torrent damage for $1297365d, stacking.", ua = "Щоразу, коли Безжальна зима завдає шкоди принаймні 1 ворогові, ви отримуєте Морозну бурю, яка надає $1297365s1% швидкості атаки та на $1297365s2% більше шкоди від Крижаного смертоносного потоку протягом $1297365d, накопичуючись." },
    { en = "Each time one of your Corruption or Immolate spells deals periodic damage, you heal $38395s1 health.", ua = "Щоразу, коли одне з ваших заклять «Зіпсуття» чи «Спалення» завдає періодичної шкоди, ви зцілюєтеся на $38395s1 здоров'я." },
    { en = "Each time the beneficial effect of your Maelstrom Weapon talent reaches 5 charges, you have a $s1% chance to gain $70831s1% attack power for $70831d.", ua = "Щоразу, коли корисний ефект вашого таланту Зброя Виру сягає 5 зарядів, ви маєте $s1% шанс отримати $70831s1% сили атаки на $70831d." },
    { en = "Each time you cast Flash Heal, your next Heal cast within $37565d has its casting time reduced by ${$37565m1/-1000}.1, stacking up to 5 times.", ua = "Щоразу, коли ви творите «Швидке зцілення», час творення вашого наступного «Зцілення», сотвореного впродовж $37565d, зменшується на ${$37565m1/-1000}.1, накопичуючись до 5 разів." },
    { en = "Each time you cast a Judgment, there is a chance it will heal all nearby party members for $37196s1.", ua = "Щоразу, коли ви читаєте «Правосуддя», є шанс, що воно зцілить усіх членів групи поблизу на $37196s1." },
    { en = "Each time you cast a Judgment, your party members gain $43838s1 mana.", ua = "Щоразу, коли ви творите Правосуддя, члени вашої групи отримують $43838s1 мани." },
    { en = "Each time you cast an offensive spell, there is a chance your next Healing Surge will cost $37234s1 less mana.", ua = "Щоразу, коли ви творите наступальне закляття, є шанс, що ваш наступний «Прилив зцілення» коштуватиме на $37234s1 менше мани." },
    { en = "Each time you cast an offensive spell, there is a chance your next spell will cost $37601s1 less mana.", ua = "Щоразу, коли ви творите наступальне закляття, є шанс, що ваше наступне закляття коштуватиме на $37601s1 менше мани." },
    { en = "Each time you gain Seething Fury, gain $408757s1 Fury and the damage of your next Eye Beam is increased by $408754s1%, stacking 5 times.", ua = "Щоразу, коли ви отримуєте «Вируючий гнів», ви отримуєте $408757s1 Гніву, а шкода вашого наступного «Променя ока» збільшена на $408754s1%, з накопиченням до 5 разів." },
    { en = "Each time you gain a Death Rune or trigger your Killing Machine talent, you also gain $90507s1% increased attack power for $90507d.  Stacks up to $90507u times.", ua = "Щоразу, коли ви отримуєте руну смерті чи спрацьовує ваш талант «Машина вбивства», ви також отримуєте на $90507s1% більше сили атаки протягом $90507d.  Накопичується до $90507u разів." },
    { en = "Each time you hit with a ranged attack, you have a chance to grant your pet $68130s1 attack power for $68130d.", ua = "Щоразу, коли ви влучаєте атакою дальнього бою, ви маєте шанс дати своєму улюбленцю $68130s1 сили атаки на $68130d." },
    { en = "Each time you kill an enemy that rewards honor or experience, gain $389088s1 Intellect for 30 seconds. Additional kills in the Storm can extend this duration for up to 5 minutes.", ua = "Щоразу, коли ви вбиваєте ворога, що дає честь або досвід, отримуйте $389088s1 Інтелекту на 30 секунд. Додаткові вбивства в Бурі можуть подовжити цю тривалість до 5 хвилин." },
    { en = "Each time you take damage from Shadow Word: Death, gain a stack of Death's Torment, increasing the initial damage of your next cast of Shadow Word: Pain by $423726s1% or increasing the damage of your next Shadow Crash by $423726s2%, stacking up to $423726U times.", ua = "Щоразу, коли ви отримуєте шкоду від «Слова тіні: Смерть», ви отримуєте стос «Муки смерті», збільшуючи початкову шкоду вашого наступного прочитання «Слова тіні: Біль» на $423726s1% або збільшуючи шкоду вашого наступного «Тіньового удару» на $423726s2%, стосуючись до $423726U разів." },
    { en = "Each time you take damage from Stagger, you have a $h% chance to make your next Purifying Brew cost no Chi.", ua = "Щоразу, коли ви отримуєте шкоду від Відкладання, ви маєте $h% шанс зробити так, що ваше наступне Очисне варево не коштуватиме Чі." },
    { en = "Each time you take damage you have a chance to activate|cFFFFFFFF Luck of the Draw!|r causing you to cast Fortifying Brew for ${$s1/1000}.1 sec. Your damage done is increased by $1217990s1% for $1217990d after|cFFFFFFFF Luck of the Draw!|r activates.", ua = "Щоразу, коли ви отримуєте шкоду, ви маєте шанс активувати|cFFFFFFFF Щасливий випадок!|r, що спонукає вас застосувати Зміцнювальне вариво на ${$s1/1000}.1 с. Ваша завдана шкода збільшується на $1217990s1% протягом $1217990d після активації|cFFFFFFFF Щасливого випадку!|r." },
    { en = "Each time you take damage you have a chance to activate|cFFFFFFFF Luck of the Draw!|r causing you to cast Survival Instincts for ${$s2/1000}.1 sec. Your damage done is increased by $1218553s1% for $1218553d after|cFFFFFFFF Luck of the Draw!|r activates.", ua = "Щоразу, коли ви отримуєте шкоду, ви маєте шанс активувати|cFFFFFFFF Щасливий випадок!|r, що змушує вас сотворити «Інстинкти виживання» на ${$s2/1000}.1 сек. Завдана вами шкода збільшується на $1218553s1% на $1218553d після активації|cFFFFFFFF Щасливого випадку!|r." },
    { en = "Each time you take damage you have a chance to activate|cFFFFFFFF Luck of the Draw!|r, causing you to cast Guardian of Ancient Kings for ${$s2/1000}.1 sec. Your damage done is increased by $1218114s1% for $1218114d after|cFFFFFFFF Luck of the Draw!|r activates.", ua = "Щоразу, коли ви отримуєте шкоду, ви маєте шанс активувати|cFFFFFFFF Щасливий випадок!|r, що спонукає вас застосувати Охоронця прадавніх королів на ${$s2/1000}.1 с. Ваша завдана шкода збільшується на $1218114s1% протягом $1218114d після активації|cFFFFFFFF Щасливого випадку!|r." },
    { en = "Each time you take damage you have a chance to cast Icebound Fortitude for ${$s1/1000} sec and gain |cFFFFFFFFLuck of the Draw!|r which increases your damage dealt by $1218601s1% for $1218601d.", ua = "Щоразу, коли ви отримуєте шкоду, ви маєте шанс сотворити Крижану стійкість на ${$s1/1000} сек і отримати |cFFFFFFFFЩасливий випадок!|r, який збільшує завдану вами шкоду на $1218601s1% на $1218601d." },
    { en = "Each time you take damage you have a chance to cast Metamorphosis for ${$s1/1000} sec and gain |cFFFFFFFFLuck of the Draw!|r which increases your damage dealt by $1219012s1% for $1219012d.", ua = "Щоразу, коли ви отримуєте шкоду, ви маєте шанс застосувати «Метаморфозу» на ${$s1/1000} сек і отримати |cFFFFFFFFЩасливий випадок!|r, що збільшує завдану вами шкоду на $1219012s1% протягом $1219012d." },
    { en = "Each time you take damage you have a chance to cast Shield Wall for ${$s2/1000}.1 sec and gain |cFFFFFFFFLuck of the Draw!|r, which increases your damage dealt by $1218163s1% for $1218163d.", ua = "Щоразу, коли ви отримуєте шкоду, ви маєте шанс застосувати Стіну щита на ${$s2/1000}.1 с і отримати |cFFFFFFFFЩасливий випадок!|r, що збільшує завдану вами шкоду на $1218163s1% протягом $1218163d." },
    { en = "Each time you trigger Tidal Waves, the cooldown of Healing Stream Totem is reduced by $s1 sec.", ua = "Щоразу, коли ви активуєте «Припливні хвилі», час відновлення «Тотема зцілювального потоку» зменшується на $s1 сек." },
    { en = "Each time you use Mangle you gain a $90166s1% increase to attack power for $90166d stacking up to $90166u times, and the duration of your Survival Instinct ability is increased by $s1%.", ua = "Щоразу, коли ви застосовуєте «Калічення», ви отримуєте збільшення сили атаки на $90166s1% протягом $90166d, накопичуючись до $90166u разів, а тривалість вашої здібності «Інстинкт виживання» збільшено на $s1%." },
    { en = "Each time you use Mortal Strike or Raging Blow you gain a $90294s1% increase to attack power for $90294d stacking up to $90294u times.", ua = "Щоразу, коли ви використовуєте «Смертельний удар» або «Шалений удар», ви отримуєте збільшення сили атаки на $90294s1% на $90294d, накопичуючись до $90294u разів." },
    { en = "Each time you use your Kill Command ability, you gain an additional $37482s1 critical strike for $37482d.", ua = "Щоразу, коли ви застосовуєте вміння «Наказ вбити», ви отримуєте додаткові $37482s1 Критичного удару протягом $37482d." },
    { en = "Each time you use your Shield Block ability, you gain $37523s1 dodge against a single attack in the next $37523d.", ua = "Щоразу, коли ви використовуєте здібність Блок щитом, ви отримуєте $37523s1 ухилення проти однієї атаки протягом наступних $37523d." },
    { en = "Each time your Immolate, Corruption and Unstable Affliction spells deal periodic damage, you have a $h% chance to gain $70840s1% damage done by you and your pet for $70840d.", ua = "Щоразу, коли ваші закляття «Спалення», «Псування» та «Нестабільна недуга» завдають періодичної шкоди, ви маєте $h% шанс збільшити шкоду, яку завдаєте ви та ваш улюбленець, на $70840s1% протягом $70840d." },
    { en = "Each time your Moonfire deals damage, it has a chance to make your next Starfire cast within $64823d instant.", ua = "Щоразу, коли ваш «Місячний вогонь» завдає шкоди, є шанс зробити ваше наступне «Зоряне полум'я», сотворене протягом $64823d, миттєвим." },
    { en = "Each time your Rejuvenation heals a target, it has a $@switch<$s2>[${$s1/100}%][${$s1/100}.1%] chance to jump to a new target at full duration.", ua = "Щоразу, коли ваше «Оздоровлення» зцілює ціль, воно має $@switch<$s2>[${$s1/100}%][${$s1/100}.1%] шанс перескочити на нову ціль з повною тривалістю." },
    { en = "Each time your Rejuvenation spell heals a target, it has a $h% chance to jump to a new target at full duration.", ua = "Щоразу, коли ваше закляття Омолодження зцілює ціль, воно має $h% шанс перестрибнути на нову ціль із повною тривалістю." },
    { en = "Each time your Shadow Word: Pain deals damage, it has a chance to grant your next spell cast within $37604d $37604s1 spell power.", ua = "Щоразу, коли ваше «Слово тіні: біль» завдає шкоди, воно має шанс дати вашому наступному закляттю, сотвореному впродовж $37604d, $37604s1 сили заклять." },
    { en = "Each wave of Arcane Missiles increases the damage of your next Arcane Blast, Arcane Pulse, or Prismatic Bolt by $1296930s1%, up to ${$1296930s1*$1296930u}%.", ua = "Кожна хвиля Арканних ракет збільшує шкоду вашого наступного Арканного вибуху, Арканного імпульсу або Призматичного спалаху на $1296930s1%, до ${$1296930s1*$1296930u}%." },
    { en = "Earth Shock and Frost Shock have a $s1% chance to cause an Elemental Overload.", ua = "«Земляний розряд» і «Морозний розряд» мають $s1% шансу спричинити «Стихійне перевантаження»." },
    { en = "Earth Shock, Earthquake, and Elemental Blast damage increased by $s1%.", ua = "Шкода від Земного удару, Землетрусу та Стихійного вибуху збільшена на $s1%." },
    { en = "Ebon Might increases allies' primary stat by an additional ${$s1}.1% of your own.", ua = "«Чорна міць» збільшує основну характеристику союзників додатково на ${$s1}.1% від вашої." },
    { en = "Ebon Might increases primary stats by an additional ${$s1/1000}.1% of your own every $456221t1 sec it remains active, up to ${$s2/1000}.1%.", ua = "«Чорна міць» збільшує основні характеристики додатково на ${$s1/1000}.1% від ваших власних кожні $456221t1 с, поки активна, до ${$s2/1000}.1%." },
    { en = "Ebon Might increases the damage of your empower spells by $s1%.", ua = "«Чорна міць» збільшує шкоду ваших підсилених заклять на $s1%." },
    { en = "Efflorescence critical heals increase the healing of your next Wild Growth by $394565s1%, stacking up to 5 times. Lifebloom critical heals reduces the cooldown of Nature's Swiftness by $s1 sec.", ua = "Критичне зцілення «Розквіту» підвищує зцілення вашого наступного «Дикого зростання» на $394565s1%, накопичуючись до 5 разів. Критичне зцілення «Життєцвіту» зменшує відновлення «Стрімкості природи» на $s1 сек." },
    { en = "Effuse critical strikes reduce the mana cost of your next Renewing Mist by $167717s1%.", ua = "Критичні удари «Виливу» зменшують вартість мани вашого наступного «Оновлювального туману» на $167717s1%." },
    { en = "Elemental Mastery also grants you $105779s1 mastery for $105779d.", ua = "«Стихійна майстерність» також надає вам $105779s1 майстерності на $105779d." },
    { en = "Empower Rune Weapon increases the damage of your next Obliterate by $1269300s1% or Frostscythe by $1269300s2%.", ua = "Підсилення рунічної зброї збільшує шкоду вашого наступного Знищення на $1269300s1% або Крижаної коси на $1269300s2%." },
    { en = "Empower Rune Weapon recharges $s1% faster and Pillar of Frost grants $s2 additional charge.", ua = "«Підсилення рунічної зброї» перезаряджається на $s1% швидше, а «Стовп морозу» дарує $s2 додатковий заряд." },
    { en = "Empower spells cast up to $s2 Living Flames at enemies or allies struck at $s1% effectiveness.", ua = "Підсилені закляття запускають до $s2 Живих полум'їв по ворогах чи вражених союзниках з $s1% ефективності." },
    { en = "Empower spells deal $s1% increased damage and cause your Obsidian Shards to blaze with power, dealing $s3% more damage for $409848d. During Dragonrage, shards always blaze with power.", ua = "Підсилені закляття завдають на $s1% більше шкоди та змушують ваші «Обсидіанові уламки» палати міццю, завдаючи на $s3% більше шкоди на $409848d. Під час «Драконячої люті» уламки завжди палають міццю." },
    { en = "Empower spells have a $s1% increased chance to critically strike and also increase your critical strike chance by $394402s1% for $394402d.", ua = "Підсилені закляття мають на $s1% більший шанс критичного удару й також збільшують ваш шанс критичного удару на $394402s1% протягом $394402d." },
    { en = "Empower spells have a $s2% chance to grant you $s1 seconds of Fury of the Aspects without causing Exhaustion.", ua = "Підсилені закляття мають $s2% шанс дати вам $s1 секунд «Люті Аспектів» без спричинення «Виснаження»." },
    { en = "Empower spells increase Reversion's healing by $394544s1% for $394544d.", ua = "Закляття підсилення збільшують зцілення «Зворотності» на $394544s1% протягом $394544d." },
    { en = "Enemies damaged by Phantom Singularity gain Infirmity for its duration and enemies damaged by Vile Taint gain Infirmity for $s1 sec, increasing damage taken by $409765s1%.", ua = "Вороги, ушкоджені «Фантомною сингулярністю», отримують «Немічність» на її тривалість, а вороги, ушкоджені «Мерзенною скверною», отримують «Немічність» на $s1 сек, що збільшує отримувану шкоду на $409765s1%." },
    { en = "Enemies hit by Avenger's Shield deal $242265s1% reduced damage to you for $242265d.", ua = "Вороги, уражені «Щитом месника», завдають вам на $242265s1% менше шкоди протягом $242265d." },
    { en = "Enemies hit by Comet Storm take $363544s1% increased damage from your Frost Spells, up to ${$363544s1*$363544u}% for $363544d.", ua = "Вороги, вражені «Кометним штормом», отримують на $363544s1% більше шкоди від ваших заклять Холоду, до ${$363544s1*$363544u}% протягом $363544d." },
    { en = "Enemies struck by Judgment or $?s204019[Blessed Hammer]?s53595[Hammer of the Righteous][Crusader Strike] take $s1% additional Holy damage. If they are struck by a critical strike the additional damage is increased by $s2%.", ua = "Вороги, вражені Судом або $?s204019[Благословенним молотом]?s53595[Молотом праведника][Ударом хрестоносця], отримують $s1% додаткової шкоди Світла. Якщо їх вражено критичним ударом, додаткова шкода збільшується на $s2%." },
    { en = "Enhanced Pyrotechnics provides an additional $s1% critical strike chance from each application.", ua = "Поліпшена піротехніка надає додаткові $s1% шансу критичного удару за кожне накладання." },
    { en = "Entering Berserk causes you to strike all nearby enemies, dealing $363830o1 Bleed damage over $363830d. Deals reduced damage beyond $s1 targets.", ua = "Активація «Берсерка» змушує вас вразити всіх ворогів поблизу, завдаючи $363830o1 шкоди кровотечею протягом $363830d. Завдає зменшеної шкоди понад $s1 цілей." },
    { en = "Entering Lunar Eclipse creates a Fury of Elune at $s1% effectiveness that follows your current target for $s2 sec.", ua = "Вхід у «Місячне затемнення» створює «Лють Елуни» з $s1% ефективності, що слідує за вашою поточною ціллю протягом $s2 сек." },
    { en = "Enveloping Mist and Renewing Mist healing increased by $s1%.", ua = "Зцілення «Огортаючого туману» й «Оновлювального туману» збільшено на $s1%." },
    { en = "Enveloping Mist reduces the target's chance to be hit with a critical strike by $170808s1% for $170808d.", ua = "«Огортаючий туман» зменшує шанс цілі отримати критичний удар на $170808s1% протягом $170808d." },
    { en = "Envenom additionally empowers itself, causing an Envenomous Explosion dealing $426581s1 Nature damage to all nearby enemies when cast with Envenom active. Deals reduced damage beyond $s2 targets. If Envenomous Explosion deals damage to a single target, it is increased by $s3%.", ua = "«Отруєння» додатково підсилює себе, викликаючи «Отруйний вибух», що завдає $426581s1 шкоди Природою всім ворогам поблизу, якщо застосоване, поки активне «Отруєння». Завдає зменшеної шкоди понад $s2 цілей. Якщо «Отруйний вибух» завдає шкоди одній цілі, її збільшено на $s3%." },
    { en = "Envenom also increases your weapon poisons' damage by $s1%.", ua = "«Отруєння» також збільшує шкоду ваших зброярських отрут на $s1%." },
    { en = "Envenom damage increased by $s1% and it increases your damage dealt by $s2%.", ua = "Шкода від Отруєння збільшена на $s1%, і воно збільшує завдану вами шкоду на $s2%." },
    { en = "Envenom deals $s1% additional damage per Bleed you have on the target.", ua = "«Отруєння» завдає на $s1% більше шкоди за кожну кровотечу, яку ви маєте на цілі." },
    { en = "Envenom refunds 1 Combo Point.", ua = "«Отруєння» повертає 1 комбо-очко." },
    { en = "Eruption damage increased by $s1% and it extends Ebon Might by an additional ${$s2/1000}.1 sec.", ua = "Шкоду Виверження збільшено на $s1%, і воно продовжує Чорну міць на ${$s2/1000}.1 сек." },
    { en = "Essence Break now applies and benefits from the effects of Cycle of Hatred, has $s1% increased initial strike damage, and has ${$s2/1000}.1 sec increased duration.", ua = "Розлам есенції тепер накладає ефекти Циклу ненависті та отримує від них користь, завдає на $s1% більше шкоди початкового удару та має на ${$s2/1000}.1 сек. більшу тривалість." },
    { en = "Essence Font and Vivify healing are increased by $s1% and your Renewing Mists on targets healed by Essence Font are extended by ${$s3}.1 sec for each direct heal.", ua = "Зцілення Джерела Есенції та Оживлення підвищено на $s1%, а ваш Оновлювальний Туман на цілях, зцілених Джерелом Есенції, подовжується на ${$s3}.1 сек за кожне пряме зцілення." },
    { en = "Essence Font has a $h% chance to grant Surge of Mists, reducing the cost of your next Enveloping Mist by $246328s1%.", ua = "«Джерело есенції» має $h% шансу дати «Приплив туманів», зменшуючи вартість вашого наступного «Огортаючого туману» на $246328s1%." },
    { en = "Essence Font's residual healing effect is increased by $s2% and lasts an additional ${$s1/1000} sec.", ua = "Залишковий зцілювальний ефект Джерела есенції збільшено на $s2%, і він триває на ${$s1/1000} сек довше." },
    { en = "Eternity Surge and Shattering Star's cooldowns are decreased by ${$s1/-1000}.1 sec and Eternity Surge now grants Essence Burst.", ua = "Відновлення «Приливу вічності» та «Розколюючої зірки» зменшено на ${$s1/-1000}.1 с, а «Прилив вічності» тепер надає «Спалах есенції»." },
    { en = "Eternity Surge grants $s1 additional $Lcharge:charges; of Azure Sweep. Casting Azure Sweep reduces the cooldown of Eternity Surge by ${$s2/1000}.1 sec.", ua = "Сплеск вічності дає $s1 додатковий $Lзаряд:заряди; Лазурового змаху. Прочитання Лазурового змаху зменшує відновлення Сплеску вічності на ${$s2/1000}.1 сек." },
    { en = "Ethereal Rampage additionally increases the damage of your next Between the Eyes by $458826s1%, stacking up to $458826u times.", ua = "«Ефірне буйство» додатково збільшує шкоду вашого наступного «Пострілу межи очі» на $458826s1%, накопичуючись до $458826u разів." },
    { en = "Every $m1 Lightning Bolt or Chain Lightning casts, your total spell haste is increased by $189063m1% for $189063d. Every $189063t2 sec the effect diminishes.", ua = "Кожні $m1 сотворінь «Блискавки» або «Ланцюгової блискавки» збільшують ваш загальний Поспіх заклять на $189063m1% на $189063d. Кожні $189063t2 сек ефект слабшає." },
    { en = "Every $s1 $?s207311[Clawing Shadows][Scourge Strikes] that burst Festering Wounds applies Soul Reaper on your target and summons an Army of the Dead ghoul for $s3 seconds.", ua = "Кожні $s1 $?s207311[Дряпучих тіней][Ударів погибелі], що розривають Гнійні рани, накладають на вашу ціль Женця душ і прикликають гуля з Армії мертвих на $s3 секунд." },
    { en = "Every $s1 Death Coils, Pestilences, or Soul Reapers will add one charge to your next Bone Shield.", ua = "Кожні $s1 «Смертельних кайданів», «Морів» чи «Жниварів душ» додають один заряд до вашого наступного «Кістяного щита»." },
    { en = "Every $s1 Focus spent reduces the cooldown of Wildfire Bomb by ${$m2/1000}.1 sec.", ua = "Кожні витрачені $s1 Зосередження зменшують час відновлення «Бомби дикого вогню» на ${$m2/1000}.1 с." },
    { en = "Every $s1 Focus you spend has a ${$m2/10}.1% chance to reset the cooldown of Rapid Fire and cause your next Rapid Fire to shoot $431156s1% additional shots during its channel.", ua = "Кожні $s1 Зосередження, які ви витрачаєте, мають ${$m2/10}.1% шансу скинути відновлення «Швидкого вогню» та змусити ваш наступний «Швидкий вогонь» зробити на $431156s1% більше пострілів під час каналювання." },
    { en = "Every $s1 Focus you spend reduces the cooldown of Trueshot by 1 sec.", ua = "Кожні $s1 Фокусування, які ви витрачаєте, зменшують відновлення «Влучного пострілу» на 1 сек." },
    { en = "Every $s1 Fury you spend, gain Seething Fury, increasing your Agility by $408737s1% for $408737d.", ua = "За кожні $s1 Гніву, які ви витрачаєте, ви отримуєте «Клекітливий гнів», що збільшує вашу Спритність на $408737s1% протягом $408737d." },
    { en = "Every $s1 Runes spent increases the Strength bonus of your next Pillar of Frost by $s2%.", ua = "Кожні $s1 витрачених рун збільшують бонус до Сили вашого наступного «Стовпа морозу» на $s2%." },
    { en = "Every $s1 Runic Power spent while Pillar of Frost is active increases the duration of Pillar of Frost by ${$m2/10}.1 sec.", ua = "Кожні $s1 рунної сили, витрачені під час дії «Стовпа морозу», збільшують його тривалість на ${$m2/10}.1 с." },
    { en = "Every $s1 Soul Shards spent grants Ritual of Ruin, making your next Chaos Bolt or Rain of Fire consume no Soul Shards and have no cast time.", ua = "Кожні витрачені $s1 Уламки душі дають «Ритуал руїни», завдяки якому ваш наступний «Хаос-заряд» або «Дощ вогню» не витрачає Уламків душі й не має часу прочитання." },
    { en = "Every $s1 sec, $s2 $lally:allies; inside of Healing Rain $lgains:gain; a watery shield that absorbs $1300642s1 damage for $1300642d.", ua = "Кожні $s1 сек. $s2 $lсоюзник:союзники; всередині Зцілювального дощу $lотримує:отримують; водяний щит, що поглинає $1300642s1 шкоди протягом $1300642d." },
    { en = "Every $s1 stacks of Tigereye Brew consumed cause your next Rising Sun Kick, Blackout Kick, or Fists of Fury to consume 1 less Chi.", ua = "Кожні $s1 спожитих зарядів Вариво Тигрового Ока роблять так, що ваш наступний Копняк Вранішнього Сонця, Затьмарливий Копняк або Кулаки Люті витрачають на 1 Чі менше." },
    { en = "Every 10 Maelstrom consumed by Earth Shock increases your critical strike damage by $s1% for $167205d.", ua = "Кожні 10 виру, поглинуті «Земним ударом», збільшують вашу критичну шкоду на $s1% протягом $167205d." },
    { en = "Every third Prescience lasts $s1% longer.", ua = "Кожне третє «Передбачення» триває на $s1% довше." },
    { en = "Every time you dodge an attack, the remaining cooldown of Breath of Fire is reduced by ${$s1/10}.1 sec.", ua = "Щоразу, коли ви ухиляєтеся від атаки, залишок відновлення «Подиху вогню» зменшується на ${$s1/10}.1 с." },
    { en = "Every time you gather a Healing Sphere, the remaining cooldowns of your Ironskin Brew and Purifying Brew are reduced by $s1 sec.", ua = "Щоразу, коли ви збираєте Зцілювальну сферу, залишкове відновлення вашого Залізошкірого вариву та Очисного вариву зменшується на $s1 сек." },
    { en = "Every time your Soothing Mist heals a target your critical strike chance is increased by $167732s1%.", ua = "Щоразу, коли ваш «Заспокійливий туман» зцілює ціль, ваш шанс критичного удару збільшується на $167732s1%." },
    { en = "Eviscerate and Black Powder increase the damage and critical strike chance of your next $?s200758[Gloomblade][Backstab], Shadowstrike, or Shuriken Storm by $394894s1% per combo point spent.", ua = "«Потрошіння» та «Чорний порох» збільшують шкоду й шанс критичного удару вашого наступного $?s200758[«Похмурого клинка»][«Удару в спину»], «Тіньового удару» або «Бурі сюрікенів» на $394894s1% за кожне витрачене комбо-очко." },
    { en = "Execute's chance to critically strike increased by $s1%.", ua = "Шанс критичного удару Страти збільшено на $s1%." },
    { en = "Explosive Shot casts have a $s1% chance to not consume a charge of Lock and Load.  Aimed Shot has a $s2% increased critical strike chance. Offensive abilities used during Bestial Wrath increase all damage you deal by $144670s1% and all damage dealt by your pet by $145737s1%, stacking up to $144670u times.", ua = "Прочитання «Вибухового пострілу» має $s1% шанс не витратити заряд «Заряджай і пали».  «Прицільний постріл» має на $s2% більший шанс критичного удару. Наступальні здібності, використані під час «Звірячого гніву», збільшують усю шкоду, яку ви завдаєте, на $144670s1% і всю шкоду, завдану вашим улюбленцем, на $145737s1%, накопичуючись до $144670u разів." },
    { en = "Explosive Shot lasts ${$m1/1000}.1 sec longer and deals $s2% increased damage.", ua = "Вибуховий постріл триває на ${$m1/1000}.1 сек. довше та завдає на $s2% більше шкоди." },
    { en = "Expurgation deals $s1% increased damage.", ua = "«Очищення» завдає на $s1% більше шкоди." },
    { en = "Expurgation lasts an additional ${$s2/1000} sec and deals $s1% increased damage. Casting Judgment or Divine Toll on a target with Expurgation causes Wrathful Sanction, damaging the target for $424590s1 Holy damage and resonating ${$424590s1/$424590s2} Holy damage to up to $s3 nearby enemies.", ua = "Викорінення триває на ${$s2/1000} сек довше й завдає на $s1% більше шкоди. Прочитання Присуду або Божественного дзвону на цілі з Викоріненням спричиняє Гнівну кару, завдаючи цілі $424590s1 святої шкоди та відлунюючи ${$424590s1/$424590s2} святої шкоди до $s3 ворогам поблизу." },
    { en = "Extra attacks from Saber Slash increase the damage of your next Run Through by $252285s1%, stacking up to $252285u times.", ua = "Додаткові атаки від «Шабельного розтину» збільшують шкоду вашого наступного «Простромлення» на $252285s1%, з накопиченням до $252285u разів." },
    { en = "Eye Beam damage increased by $s1%.", ua = "Шкода від «Променя ока» збільшена на $s1%." },
    { en = "Fatal damage causes primal energy to overload, granting immunity to all damage and harmful effects for $392255d. Can only be used outdoors in the Dragon Isles.", ua = "Смертельна шкода спричиняє перевантаження первісної енергії, надаючи несприйнятливість до всієї шкоди та шкідливих ефектів на $392255d. Можна використовувати лише під відкритим небом на Драконових Островах." },
    { en = "Feint also increases your Versatility by $170879s1 for $170879d.", ua = "«Фінт» також підвищує вашу Універсальність на $170879s1 на $170879d." },
    { en = "Feral Frenzy grants Smoldering Frenzy, increasing all damage you deal by $422751s1% for $422751d.", ua = "«Дике шаленство» дарує «Тліюче шаленство», збільшуючи всю завдану вами шкоду на $422751s1% протягом $422751d." },
    { en = "Feral Frenzy's cooldown is reduced by ${$s1/-1000} sec. During Smoldering Frenzy, enemies burn for $422751s6% of damage you deal as Fire over $422779d.", ua = "Відновлення Дикого шалу зменшено на ${$s1/-1000} сек. Під час Тліючого шалу вороги горять, отримуючи $422751s6% завданої вами шкоди як вогняну протягом $422779d." },
    { en = "Feral: Ferocious Bite now refreshes the duration of your Rip on targets with $s2% or less health.\nGuardian: Reduces the rage cost of your Savage Defense by ${$m1/-10}.", ua = "Лютість: Лютий укус тепер оновлює тривалість вашого Роздирання на цілях із $s2% або менше здоров'я.\nЗахисник: Зменшує витрату люті на вашу Дику оборону на ${$m1/-10}." },
    { en = "Ferocious Bite and Rip deal $s1% additional damage.", ua = "«Лютий укус» і «Роздирання» завдають на $s1% більше шкоди." },
    { en = "Final Verdict applies Expurgation at 100% effectiveness, while Divine Storm applies it at 50% effectiveness.", ua = "«Остаточний вердикт» застосовує «Очищення» на 100% ефективності, а «Божественна буря» — на 50% ефективності." },
    { en = "Fingers of Frost increases Shatter's damage by $s1%.", ua = "«Пальці морозу» збільшують шкоду «Розколу» на $s1%." },
    { en = "Finishing moves deal ${$s1/10}.1% more damage per combo point spent.", ua = "Завершальні прийоми завдають на ${$s1/10}.1% більше шкоди за кожне витрачене очко комбо." },
    { en = "Fire Blast, Phoenix Flames, and Fireball deal $s1% increased damage and their chance to critically strike is increased by $s3%.", ua = "Вогняний Вибух, Полум'я Фенікса та Вогняна Куля завдають на $s1% більше шкоди, а їхній шанс критичного удару підвищений на $s3%." },
    { en = "Fire Nova reduces the cooldown of Crash Lightning by ${$m1/1000}.1 sec and increases the damage of your next Crash Lightning by $1299991s1%, stacking up to $1299991u times.", ua = "Вогняна нова зменшує відновлення Розтрощувальної блискавки на ${$m1/1000}.1 сек. та збільшує шкоду вашої наступної Розтрощувальної блискавки на $1299991s1%, накопичуючись до $1299991u разів." },
    { en = "Fireball has a $h% chance to cause your next Pyroblast or Flamestrike to be a guaranteed critical strike.", ua = "«Вогняна куля» має $h% шанс зробити ваш наступний «Вогняний вибух» чи «Полум'яний удар» гарантованим критичним ударом." },
    { en = "Fists of Fury applies $s1 $Lstack:stacks; of|cFFFFFFFF Winning Streak!|r when cast and when finished channeling completely. The damage of your next Fists of Fury is increased by $1216498s1% per stack when|cFFFFFFFF Winning Streak!|r is removed.\n\nYour |cFFFFFFFF Winning Streak!|r is always removed once it reaches max stacks.", ua = "Кулаки люті накладають $s1 $Lзаряд:заряди;|cFFFFFFFF Переможної серії!|r при застосуванні та після повного завершення каналювання. Шкода вашого наступного Кулаків люті збільшена на $1216498s1% за заряд, коли|cFFFFFFFF Переможна серія!|r знімається.\n\nВаша |cFFFFFFFF Переможна серія!|r завжди знімається, щойно досягає максимуму зарядів." },
    { en = "Fists of Fury deals $s1% increased damage to the primary target and increases Shadowflame Nova damage you deal to all targets hit by $411376s2% for $411376d.", ua = "«Кулаки люті» завдають на $s1% більше шкоди головній цілі й збільшують шкоду «Нови тіньового полум'я», яку ви завдаєте всім враженим цілям, на $411376s2% протягом $411376d." },
    { en = "Fists of Fury increases the damage dealt by your next 2 Rising Sun Kicks or Spinning Crane Kicks by $394944s1%.", ua = "«Кулаки люті» збільшують шкоду ваших наступних 2 «Ударів висхідного сонця» або «Обертових ударів журавля» на $394944s1%." },
    { en = "Fists of Fury increases the damage of your next Rising Sun Kick by $1297033s1% or Spinning Crane Kick by $1297033s2% each time it strikes, stacking up to $1297033u times.", ua = "Кулаки люті збільшують шкоду вашого наступного Удару вранішнього сонця на $1297033s1% або Обертового удару журавля на $1297033s2% щоразу, коли б'ють, накопичуючись до $1297033u разів." },
    { en = "Fists of Fury now instead enhances your next $s1 Rising Sun Kicks or Spinning Crane Kicks and enhanced kicks increase the damage of your next Fists of Fury by $394949s1%, stacking up to 3 times.", ua = "«Кулаки люті» тепер натомість посилюють ваші наступні $s1 «Удари сонця, що сходить» або «Обертові удари журавля», а посилені удари збільшують шкоду ваших наступних «Кулаків люті» на $394949s1%, накопичуючись до 3 разів." },
    { en = "Fists of Fury reduces the cooldown of Storm, Earth, and Fire by $s1 sec.", ua = "«Кулаки люті» зменшують відновлення «Бурі, Землі і Вогню» на $s1 с." },
    { en = "Fists of Fury strikes an additional time at the start of its channel at $s1% effectiveness.", ua = "Кулаки люті б'ють додатковий раз на початку каналювання з $s1% ефективністю." },
    { en = "Flash Heal, Shadow Mend, and Power Word: Radiance healing increased by $s1%.", ua = "Зцілення «Швидкого оздоровлення», «Тіньового загоєння» й «Слова сили: Сяйво» збільшено на $s1%." },
    { en = "Flash of Light and Holy Light transfer $s1% additional healing to your Beacon of Light target.", ua = "«Спалах світла» й «Священне світло» передають додаткові $s1% зцілення на ціль вашого «Маяка світла»." },
    { en = "Flourish increases the rate of your heal over time effects by $408546s3% for an additional $408546d after it ends. Verdant Infusion causes your Swiftmend target to gain $408571s1% increased healing from you for $408571d.", ua = "Розквіт збільшує частоту ваших ефектів зцілення в часі на $408546s3% ще протягом $408546d після завершення. Буйне вливання спричиняє, що ціль вашого Швидкозцілення отримує на $408571s1% більше зцілення від вас протягом $408571d." },
    { en = "Flurry and Ice Lance damage increased by $s1%. Flurry causes an explosion on impact, dealing $s2% of its damage to nearby enemies, damage reduced beyond $s3 targets.", ua = "Шкода «Шквалу» та «Крижаного списа» збільшена на $s1%. «Шквал» спричиняє вибух під час влучання, завдаючи $s2% своєї шкоди ворогам поблизу; шкода зменшена понад $s3 цілей." },
    { en = "Flurry damage increased by $s1% and Flurry has a $s3% chance to grant Fingers of Frost.", ua = "Шкоду «Шквалу» збільшено на $s1%, а «Шквал» має $s3% шанс дати «Пальці морозу»." },
    { en = "For $131547d after casting Death Grip, you may cast the spell a second time without regard for its cooldown.", ua = "Протягом $131547d після творіння «Хватки смерті» ви можете застосувати це закляття вдруге, незважаючи на його відновлення." },
    { en = "For $144500d after Demoralizing Shout falls off your targets, you gain Rage from taking damage.", ua = "Протягом $144500d після того, як «Деморалізуючий крик» спадає з ваших цілей, ви отримуєте Лють від зазнаної шкоди." },
    { en = "For $144964d after using Unleash Elements, your attacks have a chance to unleash a random weapon imbue.", ua = "Протягом $144964d після використання «Вивільнення стихій» ваші атаки мають шанс вивільнити випадкове насичення зброї." },
    { en = "For $211657d after activating Voidform, the cooldown on Void Bolt is reduced by $211657s1%.", ua = "Протягом $211657d після активації «Форми Порожнечі» відновлення «Блискавки Порожнечі» зменшується на $211657s1%." },
    { en = "For $247237d after casting Light of Dawn, your healing spells will transfer an additional $247237s1% to your Beacon of Light target.", ua = "Протягом $247237d після творення «Світла світанку» ваші зцілювальні закляття передаватимуть додаткові $247237s1% на ціль вашого «Маяка світла»." },
    { en = "For $410018d after you consume Stormkeeper, your Lightning Bolt, Lava Burst, Icefury, and Frost Shock generate $410018s1% more Maelstrom, and your Chain Lightning, Lava Beam, and Earthquake deal $410018s2% increased critical damage.", ua = "Протягом $410018d після використання «Хранителя бурі» ваші «Блискавка», «Вибух лави», «Крижана лють» та «Морозний шок» генерують на $410018s1% більше Виру, а ваші «Ланцюгова блискавка», «Промінь лави» та «Землетрус» завдають на $410018s2% більше критичної шкоди." },
    { en = "For $410218d after Last Stand ends, Shield Slam unleashes a wave of force dealing $410219s2 Physical damage to enemies in front of you and reducing damage they deal to you by $410219s3% for $410219d.", ua = "Протягом $410218d після завершення «Останнього рубежу» «Удар щитом» вивільняє хвилю сили, що завдає $410219s2 фізичної шкоди ворогам перед вами та зменшує шкоду, яку вони вам завдають, на $410219s3% протягом $410219d." },
    { en = "For $m1 sec following the summon of an Elemental, you are immune to silence and interupt effects.", ua = "Протягом $m1 сек після прикликання елементаля ви несприйнятливі до ефектів мовчання та переривання." },
    { en = "For each Arcane Charge, Arcane Blast critical strike chance is increased by $s1% and Arcane Explosion critical strike chance is increased by $s2%.", ua = "За кожен «Арканний заряд» шанс критичного удару «Арканного вибуху» збільшено на $s1%, а шанс критичного удару «Арканного спалаху» — на $s2%." },
    { en = "For each bleed effect consumed from a target, your damage taken is reduced by an additional $s1%. When Shield Slam consumes a bleed, the cooldown of Thunder Clap is reset and the cooldown of Thunderous Roar is reduced by ${$s2/1000}.1 sec.", ua = "За кожен ефект кровотечі, поглинутий із цілі, отримувана вами шкода зменшується ще на $s1%. Коли Удар щитом поглинає кровотечу, відновлення Громового удару скидається, а відновлення Громового рику зменшується на ${$s2/1000}.1 сек." },
    { en = "For each combo point spent, finishing moves increase your Rip, Rake, and Thrash damage by $394465s2% and increase the chance for Shred, Rake, $?s202028[Brutal Slash][Swipe], and Thrash to Critically Strike by $394465s1% for $394465d.", ua = "За кожну витрачену очко комбо завершальні прийоми підвищують шкоду «Роздирання», «Кігтя» та «Молотіння» на $394465s2% і підвищують шанс критичного удару «Шматування», «Кігтя», $?s202028[«Жорстокого розсічення»][«Замаху»] та «Молотіння» на $394465s1% на $394465d." },
    { en = "For each stack of Brewmaster's Rhythm, Purifying Brew clears $s1% more of your damage delayed with Stagger.", ua = "За кожен заряд Ритму Броваря Очисне Вариво знімає на $s1% більше вашої шкоди, відкладеної Хитанням." },
    { en = "For every $s1 Mana spent on and during Arcane Surge, your spell damage is increased by ${$409022s1}.1% for $409022d after Arcane Surge fades, stacking up to $s2 times. Mana regeneration is increased by $409022s2% for this time.", ua = "За кожні $s1 Мани, витрачені на «Сплеск арканної сили» та під час нього, шкода ваших заклять збільшується на ${$409022s1}.1% протягом $409022d після завершення «Сплеску арканної сили», накопичуючись до $s2 разів. Відновлення Мани при цьому збільшено на $409022s2%." },
    { en = "Fracture damage increased by $s1%.", ua = "Шкоду «Перелому» збільшено на $s1%." },
    { en = "Fracture has a $s1% chance to spark a violent detonation, causing $1276488s1 Fire damage onto nearby enemies. Damage reduced beyond $s2 targets.", ua = "Перелом має $s1% шанс викликати нищівний вибух, завдаючи $1276488s1 шкоди Вогнем ворогам поблизу. Шкода зменшена понад $s2 цілей." },
