    { en = "Frost Bolt has a $s1% increased chance to trigger Brain Freeze.", ua = "«Крижана стріла» має на $s1% більший шанс спричинити «Крижаний розум»." },
    { en = "Frostbolt deals $s1% increased damage to snared targets.", ua = "«Морозна стріла» завдає на $s1% більше шкоди сповільненим цілям." },
