    { en = "Genesis duration is increased by ${$s1/1000} sec, and gaining Genesis grants Clearcasting.", ua = "Тривалість Генези збільшена на ${$s1/1000} сек., а отримання Генези надає Ясне мислення." },
    { en = "Getting stunned, silenced, interrupted, or feared generates 1 Soul Shard. Can only occur once every $s1 sec.", ua = "Приголомшення, знімовлення, переривання чи страх породжують 1 уламок душі. Може статися лише раз на $s1 с." },
