    { en = "Gives your finishing moves a $s2% chance per combo point to add a combo point to your target.", ua = "Надає вашим завершальним прийомам $s2% шанс за кожне очко комбо додати очко комбо на вашу ціль." },
    { en = "Gives your melee finishing moves a $h1% chance to add $70802s1 combo points to your target.", ua = "Дає вашим завершальним прийомам ближнього бою $h1% шансу додати $70802s1 очок комбо на вашу ціль." },
