    { en = "Grants your pet $s1 mana per 5 sec.", ua = "Надає вашому улюбленцю $s1 мани кожні 5 с." },
    { en = "Green spells restore $s1% more health, and Verdant Embrace has a $s2% chance to grant Essence Burst.", ua = "Зелені закляття відновлюють на $s1% більше здоров'я, а Зелені обійми мають $s2% шанс надати Спалах есенції." },
