    { en = "Harvesting $s1 or more Soul Fragments with Reap has a $s2 chance to cause your next Consume to be instant cast and explode in a Soulburst, dealing $1297432s1 Cosmic damage to nearby enemies.", ua = "Збирання $s1 або більше Фрагментів душі за допомогою Жнив має $s2 шанс зробити ваше наступне Поглинання миттєвим та вибухнути Вибухом душі, завдаючи $1297432s1 космічної шкоди ворогам поблизу." },
    { en = "Heal, Flash Heal, and Prayer of Healing have a $s1% chance to cast again at $s2% effectiveness.", ua = "Зцілення, Швидке Зцілення та Молитва Зцілення мають $s1% шанс сотворитися знову з $s2% ефективністю." },
    { en = "Heal, Smite, and Mind Blast have a chance to increase your Mastery by $221656s1 for $221656d.", ua = "«Зцілення», «Кара» та «Удар розумом» мають шанс підвищити вашу Майстерність на $221656s1 на $221656d." },
    { en = "Healing Wave and Chain Heal have a chance to create a Healing Rain at the target's location for ${$m1/1000}.1 sec.", ua = "Зцілювальна хвиля та Ланцюгове зцілення мають шанс створити Зцілювальний дощ у місці цілі на ${$m1/1000}.1 сек." },
    { en = "Healing Wave and Healing Surge casts have a $h% chance to heal a player standing in your Healing Rain for $s1% of the amount.", ua = "Застосування «Хвилі зцілення» та «Припливу зцілення» мають $h% шанс зцілити гравця, що стоїть у вашому «Зцілющому дощі», на $s1% від значення." },
    { en = "Healing from Rejuvenation has a $h% chance to grant Renewing Bloom, healing $364686o1 over $364686d. Swiftmend can consume Renewing Bloom.", ua = "Зцілення від «Оновлення» має $h% шанс дарувати «Відроджувальний цвіт», зцілюючи на $364686o1 протягом $364686d. «Швидке зцілення» може витрачати «Відроджувальний цвіт»." },
    { en = "Healing from your Enveloping Mist, Essence Font, and Vivify is increased by $s1% on targets with your Renewing Mist.", ua = "Зцілення вашого «Огортального туману», «Джерела есенції» та «Оживлення» збільшено на $s1% для цілей із вашим «Оновлювальним туманом»." },
    { en = "Healing is increased by $s1%.", ua = "Зцілення збільшено на $s1%." },
    { en = "Healing with Holy Shock has a $h% chance to grant you $99069s1% of your base mana.", ua = "Зцілення за допомогою «Священного шоку» має $h% шанс подарувати вам $99069s1% вашої базової мани." },
    { en = "Heart Strike and Blood Boil deal $s1% increased damage and have a $s2% chance to grant Vampiric Blood for ${$s3/1000} sec.", ua = "«Удар у серце» та «Кипіння крові» завдають на $s1% більше шкоди й мають $s2% шансу дати «Вампірську кров» на ${$s3/1000} сек." },
    { en = "Heart Strike and Marrowrend generate $s1% increased Runic Power.", ua = "Удар у серце і Кісткодер генерують на $s1% більше рунічної сили." },
    { en = "Heart Strike has a $m1% chance to generate an extra ${$m2/10} Runic Power.", ua = "«Удар у серце» має $m1% шансу згенерувати додаткові ${$m2/10} Рунічної сили." },
