    { en = "Hitting a |cFFFFFFFFJackpot!|r infuses your pet with a mutagen, causing its auto-attacks to deal $1218004s1 Nature damage to its target and up to ${$1218004i-1} enemies within $1218004a1 yds for $1218003d. Mutagenic attacks reduce the cooldown of Bestial Wrath by ${$1218004s2/100}.2 sec.", ua = "Влучання в |cFFFFFFFFДжекпот!|r наповнює вашого улюбленця мутагеном, змушуючи його автоатаки завдавати $1218004s1 шкоди Природою по цілі та до ${$1218004i-1} ворогів у межах $1218004a1 м на $1218003d. Мутагенні атаки зменшують час відновлення «Звіриного гніву» на ${$1218004s2/100}.2 с." },
    { en = "Hitting an enemy with Tiger Palm or Spinning Crane Kick grants Brewmaster's Rhythm, increasing damage dealt and reducing damage taken by ${$394797s1}.1% for $394797d, stacking up to 4 times.", ua = "Влучання по ворогу «Долонею тигра» чи «Обертовим ударом журавля» дарує «Ритм пивовара», збільшуючи завдану шкоду й зменшуючи отриману шкоду на ${$394797s1}.1% протягом $394797d, накопичуючись до 4 разів." },
    { en = "Holy Light, Crusader Strike, and Avenger's Shield have a chance to increase your Haste by $221654s1 for $221654d.", ua = "«Священне світло», «Удар хрестоносця» та «Щит месника» мають шанс підвищити ваш Поспіх на $221654s1 протягом $221654d." },
