    { en = "Increases your pet's stamina by $21927s1 and all spell resistances by $21927s2.", ua = "Підвищує витривалість вашого улюбленця на $21927s1 і всі опори до заклять на $21927s2." },
    { en = "Inflicts $23590s1 additional Holy damage on the target of a Paladin's Judgment.", ua = "Завдає $23590s1 додаткової шкоди Світлом цілі Правосуддя паладина." },
    { en = "Infused with the spirit of Midsummer.", ua = "Наповнено духом Середини Літа." },
    { en = "Infusion of Light also increases the healing done by Holy Light and Holy Radiance by $144624s1%.", ua = "«Вливання Світла» також підвищує зцілення «Святого світла» та «Святої сяйності» на $144624s1%." },
