    { en = "Infusion of Light increases the healing of Flash of Light by an additional $s1% and the absorb from Greater Judgment by an additional $s2%.", ua = "Вливання світла збільшує зцілення Спалаху світла ще на $s1% і поглинання від Вищого суду ще на $s2%." },
    { en = "Insanity drains $?s193223[$s2][$s1]% slower while in Voidform.", ua = "Безумство спадає на $?s193223[$s2][$s1]% повільніше у «Формі Порожнечі»." },
    { en = "Intellect increased by $s1.", ua = "Інтелект збільшено на $s1." },
    { en = "Interrupting a spell with Skull Bash resets the cooldown of Tiger's Fury.", ua = "Переривання закляття «Ударом черепом» скидає відновлення «Тигрячої люті»." },
    { en = "Ironfur also increases heals done to you by $m1% while active.", ua = "«Залізна шкура», поки активна, також збільшує зцілення, яке ви отримуєте, на $m1%." },
    { en = "Ironskin Brew is $s1% more effective.", ua = "«Залізошкіре вариво» на $s1% ефективніше." },
    { en = "Judgment also increases the damage of $?s198034[Divine Hammer][Blade of Justice] by $246973s1% for $246973d.", ua = "Правосуддя також підвищує шкоду $?s198034[Божественного Молота][Клинка Правосуддя] на $246973s1% на $246973d." },
    { en = "Judgment and Hammer of Wrath deal $s1% increased damage and $s2% increased critical strike damage. Hammer of Wrath applies Judgment to enemies.", ua = "«Присуд» та «Молот гніву» завдають на $s1% більше шкоди й на $s2% більше критичної шкоди. «Молот гніву» накладає «Присуд» на ворогів." },
    { en = "Judgment critical strikes apply Heartfire and can trigger Grand Crusader.", ua = "Критичні удари «Присуду» накладають «Серцевий вогонь» і можуть спрацьовувати «Великого хрестоносця»." },
    { en = "Judgment damage increased by $s1%.", ua = "Шкоду «Правосуддя» збільшено на $s1%." },
    { en = "Judgment grants a stack of Sanctification, reducing your damage taken by ${$abs($424616s1)}.1% per stack. Upon reaching $424616U stacks, your next cast of Consecration is empowered, increasing its damage and healing by $424622s1% and its radius by $424622s2%. Sanctification's stacks are reset when your empowered Consecration ends.", ua = "«Правосуддя» дає заряд «Освячення», зменшуючи отримувану вами шкоду на ${$abs($424616s1)}.1% за заряд. Досягнувши $424616U зарядів, ваше наступне прочитання «Освячення землі» посилюється, збільшуючи його шкоду та зцілення на $424622s1%, а радіус — на $424622s2%. Заряди «Освячення» скидаються, коли посилене «Освячення землі» завершується." },
    { en = "Judgment has a $h% chance to reset the cooldown of Avenger's Shield.", ua = "«Присуд» має $h% шанс скинути відновлення «Щита месника»." },
    { en = "Judgment increases the damage enemies take from your Holy Power spenders by an additional $s1%. Hammer of Wrath now hits $s3 nearby targets for $s4% of its damage.", ua = "«Присуд» підвищує шкоду, яку вороги отримують від ваших здібностей, що витрачають Священну силу, додатково на $s1%. «Молот гніву» тепер уражає $s3 сусідніх цілей на $s4% своєї шкоди." },
    { en = "Judgment now has a $s1% chance to grant Infusion of Light. Holy Light now has a $s2% chance to grant Infusion of Light.", ua = "Суд тепер має $s1% шанс надати Вливання світла. Святе світло тепер має $s2% шанс надати Вливання світла." },
    { en = "Judgment, Blade of Justice, and $?a384052[Radiant Decree][Wake of Ashes] damage increased by $s1%.", ua = "Шкода Правосуддя, Клинка Правосуддя та $?a384052[Сяйливого Указу][Слід Попелу] підвищена на $s1%." },
    { en = "Keg Smash damage increased by $s1%. Breath of Fire damage increased by $s2%.", ua = "Шкода Удару барилом збільшена на $s1%. Шкода Вогняного подиху збільшена на $s2%." },
    { en = "Keg Smash deals $s1% additional damage, heals you for $s2% of damage dealt, and grants $s3% of damage dealt as maximum health for $366794d, stacking up to $366794u times.", ua = "«Удар бочкою» завдає на $s1% більше шкоди, зцілює вас на $s2% завданої шкоди та дарує $s3% завданої шкоди як максимальне здоров'я протягом $366794d, накопичуючись до $366794u разів." },
    { en = "Keg Smash's Energy cost is reduced by $s1 and when it strikes a target afflicted by Breath of Fire it deals $1272464s1 additional Fire damage.", ua = "Витрату Енергії на «Удар барилом» зменшено на $s1, і коли він влучає в ціль, уражену «Подихом вогню», він завдає $1272464s1 додаткової шкоди Вогнем." },
    { en = "Kill Command critical hits empower your next Cobra Shot or Multi-Shot, increasing the damage and cooldown reduction of Cobra Shot by $363760s1% or causing Multi-Shot to grant an additional ${$m3/1000}.1 sec of Beast Cleave.", ua = "Критичні влучання «Наказу вбити» підсилюють ваш наступний «Постріл кобри» або «Мультипостріл», збільшуючи шкоду й зменшення часу відновлення «Пострілу кобри» на $363760s1% або надаючи «Мультипостілу» додаткові ${$m3/1000}.1 сек «Звіриного розтину»." },
    { en = "Kill Command damage increased by $s1% and it has a $h% chance to reset the cooldown on Barbed Shot.", ua = "Шкода «Наказу вбити» підвищена на $s1%, і він має $h% шанс скинути відновлення «Колючого пострілу»." },
    { en = "Kill Command has a chance to reset the cooldown of Bestial Wrath.", ua = "Наказ убити має шанс скинути відновлення Звіриного гніву." },
    { en = "Kill Command, Aimed Shot, and Mongoose Bite have a chance to increase your Haste by $221643s1 for $221643d.", ua = "«Наказ убити», «Прицільний постріл» і «Укус мангуста» мають шанс збільшити ваш Поспіх на $221643s1 на $221643d." },
    { en = "Kill Shot deals $s1% increased damage and reduces the cooldown of Aimed Shot and Rapid Fire by ${$m2/1000}.1 sec.", ua = "«Смертельний постріл» завдає на $s1% більше шкоди і зменшує час відновлення «Прицільного пострілу» та «Швидкого вогню» на ${$m2/1000}.1 с." },
    { en = "Killing Machine and Sudden Doom grant $144901s1 Haste or Mastery, whichever is highest, for $?s63560[15][${$hnd*2+4}] sec, stacking up to $144901u times.", ua = "«Машина вбивства» та «Раптова згуба» надають $144901s1 Поспіху або Майстерності (більше зі значень) на $?s63560[15][${$hnd*2+4}] сек, накопичуючись до $144901u разів." },
    { en = "Killing Spree deals $s1% more damage every time it strikes a target. Abilities against a target with Vendetta on it increase your mastery by $145249s1 for $145249d, stacking up to $145249u times. Every time you Backstab, you have a $s3% chance to replace your Backstab with Ambush that can be used regardless of Stealth.", ua = "«Вбивчий шал» завдає на $s1% більше шкоди щоразу, коли вражає ціль. Здібності проти цілі під дією «Вендети» збільшують вашу майстерність на $145249s1 протягом $145249d, накопичуючись до $145249u разів. Щоразу, коли ви завдаєте «Удар у спину», ви маєте $s3% шанс замінити «Удар у спину» на «Засідку», яку можна використати незалежно від скритності." },
    { en = "Killing a Legion dungeon boss increases your damage and healing by $234121s1% for $234121d.", ua = "Убивство боса підземелля Легіону збільшує вашу шкоду та зцілення на $234121s1% протягом $234121d." },
    { en = "Killing an enemy reduces Fleshcraft's cooldown by ${$345688s1/-1000} sec and your Critical Strike rating is increased by $s2, stacking $345691u times.", ua = "Убивство ворога зменшує відновлення «Плотоформування» на ${$345688s1/-1000} с, а ваш рейтинг Критичного удару збільшується на $s2, накопичуючись до $345691u разів." },
    { en = "Killing enemy players grants Breaker's Frenzy, increasing versatility by $385699s1% and movement speed by $385699s2%. Can stack up to $385699u times.", ua = "Убивство ворожих гравців надає «Шаленство трощителя», збільшуючи Універсальність на $385699s1% і швидкість пересування на $385699s2%. Накопичується до $385699u разів." },
    { en = "Lava Burst burns your target for $426577s1% additional damage over $427729d, and after consuming Primordial Wave, your next $426578u casts of Lava Burst to also hit up to $426578s1 additional targets affected by your Flame Shock for $426578s2% of normal damage.", ua = "«Вибух лави» пропікає вашу ціль, завдаючи $426577s1% додаткової шкоди протягом $427729d, а після поглинання «Первісної хвилі» ваші наступні $426578u прочитань «Вибуху лави» також вражають до $426578s1 додаткових цілей під дією вашого «Вогняного удару», завдаючи $426578s2% звичайної шкоди." },
    { en = "Lava Burst increases the damage of your next Earth Shock or Earthquake$?s210714[, or Frost Shock,][] by $252141s1%.", ua = "«Вибух лави» збільшує шкоду вашого наступного «Земного шоку» чи «Землетрусу»$?s210714[, або «Крижаного шоку»,][] на $252141s1%." },
    { en = "Lava Lash has an additional $h% chance to trigger Stormbringer.", ua = "«Лавовий батіг» має додатковий $h% шанс спрацювати «Буревісник»." },
    { en = "Leech increased by $s1% while in The Maw.", ua = "Висмоктування збільшено на $s1%, поки ви в Пащі." },
    { en = "Lifebloom's bloom has a $s1% chance to apply |cFFFFFFFFInsurance!|r to its target for ${$s2/1000} sec. When |cFFFFFFFFInsurance!|r is consumed or removed, it leaves a missing Rejuvenation, Regrowth, or Wild Growth heal over time effect for ${$s3/1000} sec on its target.", ua = "Розквіт «Цвіту життя» має $s1% шанс накласти на ціль |cFFFFFFFFСтрахування!|r на ${$s2/1000} с. Коли |cFFFFFFFFСтрахування!|r витрачається або знімається, воно лишає на цілі відсутній ефект періодичного зцілення «Оновлення», «Відростання» чи «Дикого росту» на ${$s3/1000} с." },
    { en = "Light's Hammer heals $s2% more frequently and generates $s6 Holy Power every $122773t2 sec. Holy Prism's healing is increased by $s3% and it generates $s4 Holy Power if cast on an enemy target, or $s5 if cast on an ally.", ua = "Молот Світла зцілює на $s2% частіше й створює $s6 Святої Сили щ $122773t2 сек. Зцілення Святої Призми підвищене на $s3%, і вона створює $s4 Святої Сили, якщо творити її на ворожій цілі, або $s5, якщо творити на союзнику." },
    { en = "Lightning Bolt, Chain Lightning, and Lava Burst increase the damage of your next $?s117014[Elemental Blast][Earth Shock] or Earthquake by ${$394651S1}.1%, stacking up to $394651u times.", ua = "«Розряд блискавки», «Ланцюгова блискавка» та «Вибух лави» збільшують шкоду вашого наступного $?s117014[«Стихійного вибуху»][«Земного удару»] чи «Землетрусу» на ${$394651S1}.1%, накопичуючись до $394651u разів." },
    { en = "Lightning Bolt, Stormstrike, and Healing Wave have a chance to increase your Critical Strike by $221665s1 for $221665d.", ua = "Розряд Блискавки, Штормовий Удар і Хвиля Зцілення мають шанс підвищити ваш Критичний удар на $221665s1 на $221665d." },
    { en = "Lingering Shadow now also benefits Eviscerate and Black Powder at $s1% effectiveness.", ua = "Тривка тінь тепер також приносить користь Патранню та Чорному пороху з $s1% ефективністю." },
    { en = "Living Flame has a chance to apply Echo at $s1% effectiveness on allies healed, or a nearby ally who doesn't already have Echo.", ua = "Живе Полум'я має шанс накласти Відлуння з $s1% ефективністю на зцілених союзників або на союзника поблизу, який ще не має Відлуння." },
    { en = "Lunar Eclipse and Solar Eclipse each increase the Astral Power Wrath generates by ${$s1/10} and Starfire generates by ${$s2/10}.", ua = "«Місячне затемнення» і «Сонячне затемнення» кожне збільшують Астральну силу, яку генерує «Гнів», на ${$s1/10}, а яку генерує «Зоряний вогонь» — на ${$s2/10}." },
    { en = "Lunar and Solar Empowerments also increase the critical strike chance of their corresponding spells by $211089s1%.", ua = "Місячне і Сонячне підсилення також збільшують шанс критичного удару відповідних заклять на $211089s1%." },
    { en = "Malefic Rapture damage increased by $s1% and its critical strike chance is increased by $s2%.", ua = "Шкоду «Лиховісного захвату» збільшено на $s1%, а його шанс критичного удару — на $s2%." },
    { en = "Malefic Rapture has a chance to increase damage dealt by your Agony, Corruption, and Unstable Affliction by $455679s1% for $455679d.", ua = "«Лиховісний захват» має шанс підвищити шкоду, завдану вашими «Агонією», «Псуванням» та «Нестабільною недугою», на $455679s1% на $455679d." },
    { en = "Malefic Rapture's damage is increased by $s1% and each cast extends the duration of Corruption, Agony, and Unstable Affliction by $s2 sec.", ua = "Шкода «Лиховісного захвату» підвищена на $s1%, а кожне застосування подовжує тривалість «Псування», «Агонії» та «Нестабільної недуги» на $s2 с." },
    { en = "Mana cost of Shadow spells reduced by $s1%.", ua = "Вартість мани заклять Тіні зменшено на $s1%." },
    { en = "Mangle reduces the cost of your next Ironfur or Frenzied Regeneration by ${$211160m1/-10} Rage, stacking up to $211160u times.", ua = "«Понівечення» зменшує вартість вашого наступного «Залізного хутра» або «Шаленого відновлення» на ${$211160m1/-10} Люті, стосуючись до $211160u разів." },
