    { en = "Rising Sun Kick critical strikes reduce the cooldown of Fists of Fury by ${$m1/1000}.1 sec.", ua = "Критичні удари «Удару висхідного сонця» зменшують відновлення «Кулаків люті» на ${$m1/1000}.1 с." },
