    { en = "Rupture deals an additional $s1% damage as Nature. Crimson Tempest deals an additional $s2% damage as Nature.", ua = "«Розрив» завдає додатково $s1% шкоди Природою. «Багряна буря» завдає додатково $s2% шкоди Природою." },
    { en = "Saber Slash has an additional $s1% chance to trigger Main Gauche.", ua = "Шаблевий розтин має додаткові $s1% шансу викликати Ліву руку." },
