    { en = "Shadow Word: Madness damage increased by $s2% and Insanity cost reduced by ${$s1/-100}.", ua = "Шкода від «Слова тіні: Безумство» збільшена на $s2%, а витрата Безумства зменшена на ${$s1/-100}." },
