    { en = "When Barkskin fades, Savage Defense is automatically activated, and a $s1 Rage Frenzied Regeneration is automatically cast.", ua = "Коли Кора згасає, автоматично активується Дика оборона й автоматично твориться Шалена регенерація на $s1 Люті." },
    { en = "When Barkskin fades, all healing done to you is increased by $253575s1% for $253575d.", ua = "Коли «Кора» зникає, усе отримане вами зцілення збільшується на $253575s1% протягом $253575d." },
    { en = "When Chaos Bolt or Rain of Fire consumes a charge of Ritual of Ruin, you summon a Blasphemy for $s1 sec.", ua = "Коли Стріла хаосу або Вогняний дощ поглинає заряд Ритуалу згуби, ви прикликаєте Блюзнірство на $s1 сек." },
    { en = "When Conflagrate critically strikes, your Fire damage is increased by $455674s1% for $455674d.", ua = "Коли «Займання» критично влучає, ваша вогняна шкода збільшується на $455674s1% протягом $455674d." },
    { en = "When Dancing Rune Weapon fades, your Rune regeneration rate is increased by $253381s1% for $253381d.", ua = "Коли «Танцююча рунічна зброя» зникає, швидкість відновлення ваших рун підвищується на $253381s1% на $253381d." },
    { en = "When Deathmark expires, Nature damage you deal is increased by $409587s1% for $409587d.", ua = "Коли «Мітка смерті» спливає, шкода Природою, яку ви завдаєте, збільшується на $409587s1% протягом $409587d." },
    { en = "When Dispersion ends, you gain $171150s1 Versatility for $171150d.", ua = "Коли Розсіювання завершується, ви отримуєте $171150s1 Універсальності протягом $171150d." },
    { en = "When Doom Brand is removed, you have a chance to summon a Doomfiend that casts $423734s2 Doom Bolt Volleys before departing. Each Doom Bolt Volley deals $<damage> Shadow damage to up to $423734x1 enemies or ${$<damage>*(1+$s2/100)} Shadow damage to a single enemy.", ua = "Коли «Тавро погибелі» знімається, ви маєте шанс призвати «Демона погибелі», який застосовує $423734s2 «Залпи заряду погибелі», перш ніж зникнути. Кожен «Залп заряду погибелі» завдає $<damage> шкоди Тіні до $423734x1 ворогів або ${$<damage>*(1+$s2/100)} шкоди Тіні одному ворогові." },
    { en = "When Dragonrage ends, Emerald Trance persists for $s1 sec per stack and grants you Essence Burst every $424402t3 sec.", ua = "Коли «Драконяча лють» завершується, «Смарагдовий транс» триває $s1 с за заряд і надає вам «Спалах есенції» кожні $424402t3 с." },
    { en = "When Earth Shield heals a target, the target will gain $s1% of the amount healed as an absorb.", ua = "Коли «Земляний щит» зцілює ціль, ціль отримує $s1% від зціленого обсягу як поглинання." },
    { en = "When Eclipse ends or when you enter combat, enter a Dreamstate, reducing the cast time of your next $s3 Starfires or Wraths by $s1% and increasing their damage by $s2%.", ua = "Коли Затемнення завершується або коли ви вступаєте в бій, ви входите в Стан сну, зменшуючи час прочитання ваших наступних $s3 Зоряних вогнів чи Гнівів на $s1% і збільшуючи їхню шкоду на $s2%." },
    { en = "When Eye Beam finishes fully channeling, your Haste is increased by $252165s1% for $252165d.", ua = "Коли «Промінь ока» завершує повне скеровування, ваш Поспіх підвищується на $252165s1% на $252165d." },
    { en = "When Fists of Fury ends, the critical strike chance of Rising Sun Kick is increased by $247255s1% for $247255d.", ua = "Коли «Кулаки люті» завершуються, шанс критичного удару «Удару висхідного сонця» збільшується на $247255s1% протягом $247255d." },
    { en = "When Flame Shock deals periodic damage, you have a $h% chance to reset the cooldown of Lava Lash.", ua = "Коли «Полум'яний шок» завдає періодичної шкоди, ви маєте $h% шанс скинути відновлення «Лавового батога»." },
    { en = "When Gift of the Serpent spheres heal a player, they gain an absorb for $s1% of the amount healed.", ua = "Коли сфери «Дару змія» зцілюють гравця, він отримує поглинання на $s1% від обсягу зцілення." },
    { en = "When Glimmer of Light dissipates or is refreshed, it creates a Holy Reverberation on its target to heal an ally for $423377o1 or damage an enemy for $423379o2 over $423377d. Multiple Holy Reverberations may overlap, up to $423377u times.", ua = "Коли «Мерехтіння світла» розсіюється або оновлюється, воно створює на цілі «Священну реверберацію», щоб зцілити союзника на $423377o1 або завдати ворогу $423379o2 шкоди протягом $423377d. Кілька «Священних реверберацій» можуть накладатися, до $423377u разів." },
    { en = "When Gore is consumed, the cooldown of Barkskin is reduced by ${$m1/1000}.1 sec.", ua = "Коли витрачається «Проштрикування», відновлення «Кори» зменшується на ${$m1/1000}.1 сек." },
    { en = "When Gust of Mists heals a target, they have a $h% chance to gain Tranquil Mist which heals them for $253448o1 health over $253448d.", ua = "Коли «Порив туманів» зцілює ціль, вона має $h% шанс отримати «Спокійний туман», що зцілює її на $253448o1 здоров'я протягом $253448d." },
    { en = "When Holy Word: Serenity or Holy Word: Sanctify finish their cooldown, you gain $394745s1% critical strike chance for $394745d.", ua = "Коли завершується відновлення «Святого слова: Умиротворення» або «Святого слова: Освячення», ви отримуєте $394745s1% шансу критичного удару на $394745d." },
    { en = "When Kill Command resets, it has a $s1% chance to make your next Wildfire Bomb incur no cooldown.", ua = "Коли «Наказ убити» скидається, він має $s1% шанс зробити так, що ваша наступна «Бомба пожежі» не спричинить відновлення." },
    { en = "When Lacerate deals damage, it also increases all damage you deal to your Lacerate target by $171103s1% for $171103d.", ua = "Коли «Терзання» завдає шкоди, воно також збільшує всю шкоду, яку ви завдаєте цілі «Терзання», на $171103s1% протягом $171103d." },
    { en = "When Overpower has its cooldown reset by Tactician, your next Mortal Strike or Cleave has its damage increased by $455485s1% and critical strike chance increased by $455485s2%, stacking up to $455485u times.", ua = "Коли відновлення «Здолання» скидається «Тактиком», ваш наступний «Смертельний удар» чи «Розсічення» завдає на $455485s1% більше шкоди й має на $455485s2% більший шанс критичного удару, накопичуючись до $455485u разів." },
    { en = "When Prayer of Mending heals a target, you and the target gain $171162s1 Versatility for $171162d. Stacks up to $171162u times.", ua = "Коли Молитва зцілення зцілює ціль, ви та ціль отримуєте $171162s1 Універсальності на $171162d. Накопичується до $171162u разів." },
    { en = "When Prayer of Mending heals a target, you have a $h% chance to reduce the cooldown of Holy Word: Sanctify by $s1 sec.", ua = "Коли «Молитва зцілення» зцілює ціль, ви маєте $h% шанс зменшити час відновлення «Слово святості: освячення» на $s1 с." },
    { en = "When Prayer of Mending jumps or expires, it increases the damage and healing of your next Holy Word by $409479s1%, stacking up to $409479u times.", ua = "Коли Молитва Оздоровлення перестрибує або добігає кінця, вона підвищує шкоду й зцілення вашого наступного Святого Слова на $409479s1%, накопичуючись до $409479u разів." },
    { en = "When Pyroblast and Flamestrike critically strike you gain Searing Rage, increasing your critical strike damage by $424285s1% for $424285d, stacking up to ${$424285s1*$424285u}%.", ua = "Коли «Піровибух» та «Полум'яний удар» завдають критичного удару, ви отримуєте «Пекучу лють», що збільшує вашу критичну шкоду на $424285s1% протягом $424285d, з накопиченням до ${$424285s1*$424285u}%." },
    { en = "When Pyroblast! activates, you have a chance to cause all Pyroblasts to have no cast time and be guaranteed critical strikes for $166868d. (Approximately ${$procrppm}.2 procs per minute)", ua = "Коли активується «Піровибух!», ви маєте шанс зробити так, що всі «Піровибухи» протягом $166868d не матимуть часу прочитання й гарантовано завдаватимуть критичних ударів. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "When Raging Blow resets its own cooldown, the damage of your next Bloodthirst is increased by $455495s1%, stacking up to $455495u times.", ua = "Коли «Шалений удар» скидає власне відновлення, шкода вашої наступної «Спраги крові» підвищується на $455495s1%, накопичуючись до $455495u разів." },
    { en = "When Rip deals damage, there is a $h% chance for it to deal damage again.", ua = "Коли «Роздирання» завдає шкоди, є $h% шансу, що воно завдасть шкоди ще раз." },
    { en = "When Rip deals damage, you have a $h% chance to cause your next Ferocious Bite to consume no Combo Points and count as if you spent the maximum amount of Energy.", ua = "Коли «Розрив» завдає шкоди, ви маєте $h% шанс зробити так, що ваш наступний «Лютий укус» не витратить очок комбо і зарахується так, ніби ви витратили максимальну кількість Енергії." },
    { en = "When Riptide's initial heal critically strikes, the healing done by your next Healing Rain is increased by $s1%.", ua = "Коли початкове зцілення «Бурхливої хвилі» завдає критичного удару, зцілення вашого наступного «Зцілювального дощу» підвищується на $s1%." },
    { en = "When Shadow Dance expires, your next finishing move refunds $170107s1 combo points.", ua = "Коли Танок Тіней добігає кінця, ваш наступний завершальний прийом повертає $170107s1 очок комбо." },
    { en = "When Starsurge hits a player, the cast time of Lunar Strike is reduced by $180719s1%, and the damage of Solar Wrath is increased by $180719s2% for $180719d.", ua = "Коли «Зоряний сплеск» влучає у гравця, час прочитання «Місячного удару» зменшується на $180719s1%, а шкода «Сонячного гніву» збільшується на $180719s2% протягом $180719d." },
    { en = "When Stormkeeper or Ascendance fade, your next $s1 $lLightning Bolt:Lighting Bolts;, $lChain Lightning:Chain Lightnings;, or $lLava Burst:Lava Bursts; deal $1300219s1% increased damage and cause your next Earthquake, Earth Shock, or Elemental Blast to cost $1300222s1% less Maelstrom.", ua = "Коли Хранитель бурі або Піднесення згасають, ваш наступний $s1 $lБлискавичний спалах:Блискавичні спалахи;, $lЛанцюгова блискавка:Ланцюгові блискавки; або $lВибух лави:Вибухи лави; завдає на $1300219s1% більше шкоди та змушує ваш наступний Землетрус, Земний удар або Стихійний вибух коштувати на $1300222s1% менше Виру." },
    { en = "When Unstable Affliction deals damage, you have a $h% chance to gain $216472s1% increased damage for $216472d.", ua = "Коли «Нестабільна недуга» завдає шкоди, ви маєте $h% шансу отримати $216472s1% збільшеної шкоди протягом $216472d." },
    { en = "When a Bone Shield charge is consumed you have a 20% chance to generate $394559s1 Rune.", ua = "Коли витрачається заряд «Кістяного щита», ви маєте 20% шанс згенерувати $394559s1 Руну." },
    { en = "When a Burning Ember fills up, your critical strike chance is increased by $145164s1% for $145164d. Haunt has a $s1% chance to refund its shard when expiring. Shadow Bolt and Touch of Chaos have a $h% chance to also cast Hand of Gul'dan at the target.", ua = "Коли «Палаюча жарина» наповнюється, ваш шанс критичного удару збільшено на $145164s1% протягом $145164d. «Переслідування» має $s1% шанс повернути свій уламок при завершенні. «Стріла темряви» й «Доторк хаосу» мають $h% шанс також накласти «Руку Ґул'дана» на ціль." },
    { en = "When a Faerie Dragon is summoned, your Arcane and Nature damage is increased by $188086m1% for $188086d.", ua = "Коли прикликається Чарівний дракон, ваша шкода Арканою та Природою підвищується на $188086m1% протягом $188086d." },
    { en = "When a Gift of the Ox Healing Sphere is consumed, your current Stagger amount is lowered by $s1%.", ua = "Коли поглинається зцілювальна сфера «Дар вола», ваш поточний рівень «Заминки» знижується на $s1%." },
    { en = "When a Shadows of the Predator application resets stacks, you gain $408468s1% increased Agility and you generate $408468s2 combo point every $408468t2 secs for $408468d.", ua = "Коли накладення «Тіней хижака» скидає заряди, ваша Спритність збільшується на $408468s1%, і ви породжуєте $408468s2 очко комбо кожні $408468t2 с протягом $408468d." },
    { en = "When a charge of Bone Shield is consumed, the cooldown of Dancing Rune Weapon is reduced by ${$m1/-1000}.1 sec.", ua = "Коли витрачається заряд «Кістяного щита», відновлення «Танцівливої рунічної зброї» скорочується на ${$m1/-1000}.1 с." },
    { en = "When an attack drops your health below $s1%, one of your Blood Runes will immediately activate and convert into a Death Rune for the next $105582d. This effect cannot occur more than once every $s2 sec.", ua = "Коли атака знижує ваше здоров'я нижче за $s1%, одна з ваших Рун крові негайно активується і перетворюється на Руну смерті на наступні $105582d. Цей ефект не може статися частіше ніж раз на $s2 с." },
    { en = "When clearing Moderate Stagger with Purifying Brew, you generate $s1 stack of Elusive Brawler.", ua = "Коли ви знімаєте «Помірне тремтіння» за допомогою «Очисного вариву», ви генеруєте $s1 заряд «Невловимого бійця»." },
    { en = "When hit by a damaging attack, you gain Fel Mending, healing you for $187649o1 over $187649d.", ua = "Коли вас уражає шкідлива атака, ви отримуєте «Скверноцілення», яке зцілює вас на $187649o1 протягом $187649d." },
    { en = "When struck in combat has a chance of causing the attacker to flee in terror for 2 seconds.", ua = "При влученні в бою має шанс змусити нападника втекти в жаху на 2 секунди." },
    { en = "When struck in combat has a chance of freezing the attacker in place for $27868d.", ua = "Під час удару в бою має шанс скувати нападника на місці на $27868d." },
    { en = "When struck in combat has a chance of returning 300 mana, 10 rage, or 40 energy to the wearer.", ua = "При влученні в бою має шанс повернути власнику 300 мани, 10 люті або 40 енергії." },
    { en = "When struck in combat has a chance of shielding the wearer in a protective shield which will absorb 350 damage.", ua = "При отриманні удару в бою має шанс огорнути власника захисним щитом, що поглине 350 шкоди." },
    { en = "When struck in melee there is a $h% chance you will Fade for $21976d.", ua = "При ударі в ближньому бою є $h% шанс, що ви «Розчинитеся» на $21976d." },
    { en = "When the phoenix is summoned, you gain $186170m2% spell damage and $186170m1% spell haste for $186170d.", ua = "Коли з'являється фенікс, ви отримуєте $186170m2% шкоди закляттів і $186170m1% поспіху закляттів на $186170d." },
    { en = "When the target of your Riptide effect drops below $m1% health, the duration is refreshed.", ua = "Коли ціль вашого ефекту «Відпливна течія» опускається нижче $m1% здоров'я, тривалість поновлюється." },
    { en = "When their energy depletes, Wild Imps have a $s3% chance to fling themselves at their target and Implode at $s1% effectiveness to their main target and $s2% effectiveness to other targets.", ua = "Коли їхня енергія вичерпується, Дикі бісенята мають $s3% шанс кинутися на свою ціль і Вибухнути з $s1% ефективністю по головній цілі та $s2% ефективністю по інших цілях." },
    { en = "When you Chain Heal, you have a $s1% chance to also apply Riptide to the primary target.", ua = "Коли ви застосовуєте «Ланцюгове зцілення», у вас є $s1% шансу також накласти «Відпливну течію» на головну ціль." },
    { en = "When you activate Dark Transformation, $s2 of your runes are automatically refreshed.", ua = "Коли ви активуєте «Темне перетворення», $s2 ваших рун автоматично оновлюються." },
    { en = "When you activate Dark Transformation, your Shadow damage dealt is increased by $166062s1% for $166062d.", ua = "Коли ви активуєте «Темну трансформацію», завдана вами шкода Тінню збільшується на $166062s1% на $166062d." },
    { en = "When you activate Divine Protection, you gain $70760s1% dodge for $70760d.", ua = "Коли ви активуєте «Божественний захист», ви отримуєте $70760s1% ухилення протягом $70760d." },
    { en = "When you activate Feral Spirits, the duration of incoming crowd control effects is reduced by $171114s1% for $171114d.", ua = "Коли ви активуєте «Диких духів», тривалість вхідних ефектів контролю зменшується на $171114s1% протягом $171114d." },
    { en = "When you activate Rapture, the mana cost of Power Word: Shield is reduced by $167695s1% for $167695d.", ua = "Коли ви активуєте «Захват», витрата мани на «Слово сили: Щит» зменшується на $167695s1% протягом $167695d." },
    { en = "When you activate Shadow Dance, you gain $165509s1 Energy every second.", ua = "Коли ви активуєте «Танець тіней», ви отримуєте $165509s1 Енергії щосекунди." },
    { en = "When you activate your Shamanistic Rage ability you also deal $70829s1% additional damage for $70829d.", ua = "Коли ви активуєте здібність «Шаманська лють», ви також завдаєте на $70829s1% більше шкоди на $70829d." },
    { en = "When you are hit by melee attacks, you have a chance to gain $37436s1 spell power for $37436d.", ua = "Коли вас вражають атаки ближнього бою, ви маєте шанс отримати $37436s1 сили заклять на $37436d." },
    { en = "When you are stunned, harden your resolve, absorbing up to ${$384986s1*(1+$@versadmg)} damage for $384986d. Cannot occur more than once every $385002d.", ua = "Коли вас приголомшено, ваша рішучість гартується, поглинаючи до ${$384986s1*(1+$@versadmg)} шкоди протягом $384986d. Не може статися частіше, ніж раз на $385002d." },
    { en = "When you benefit from Art of War, you gain Seraphim for $s1 sec.", ua = "Коли ви отримуєте вигоду від Мистецтва війни, ви отримуєте Серафима на $s1 сек." },
    { en = "When you block a physical attack, you have a chance to increase your shield block value by $167742s1% for $167742d.\n(Approximately ${$procrppm}.2 procs per minute)", ua = "Коли ви блокуєте фізичну атаку, ви маєте шанс збільшити значення блокування щитом на $167742s1% протягом $167742d.\n(Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "When you cast $?s456359[Surging Totem][Healing Rain], $?s456359[$s1][$s2] $Lally:allies; in the radius $?s456359[have][has] |cFFFFFFFFInsurance!|r applied to them. When |cFFFFFFFFInsurance!|r is consumed, your next Chain Heal, Healing Surge, or Healing Wave is increased by $?s456359[$1219323s1][$1219323s2]%.", ua = "Коли ви творите $?s456359[«Здіймаючий тотем»][«Зцілющий дощ»], $?s456359[$s1][$s2] $Lally:allies; у радіусі $?s456359[отримують][отримує] |cFFFFFFFFСтрахування!|r. Коли |cFFFFFFFFСтрахування!|r витрачається, ваше наступне «Ланцюгове зцілення», «Хвиля зцілення» чи «Хвиля зцілення» збільшується на $?s456359[$1219323s1][$1219323s2]%." },
    { en = "When you cast $s1 sequential Healing Touch spells, the mana cost of your next Wild Growth is reduced by $167715s1%.", ua = "Коли ви читаєте $s1 закляття «Зцілювальний доторк» поспіль, вартість мани вашого наступного «Буйного росту» зменшується на $167715s1%." },
    { en = "When you cast Avenger's Shield, you gain an absorb effect equal to ${$m1/10}.1% of your maximum health for $185676d.", ua = "Коли ви творите «Щит месника», ви отримуєте ефект поглинання, що дорівнює ${$m1/10}.1% вашого максимального здоров'я, на $185676d." },
    { en = "When you cast Avenging Wrath, the duration of all incoming crowd control effects on yourself is reduced by $165889s1% for $165889d.", ua = "Коли ви застосовуєте «Караючий гнів», тривалість усіх ефектів контролю натовпу, накладених на вас, зменшена на $165889s1% протягом $165889d." },
    { en = "When you cast Call Dreadstalkers, you gain $246962s1% Haste for $246962d.", ua = "Коли ви застосовуєте «Виклик жахоловів», ви отримуєте $246962s1% Поспіху на $246962d." },
    { en = "When you cast Cone of Cold, a patch of ice is left on the ground below the target area for $180723d, slowing any enemies in the area by $180724s1%.", ua = "Коли ви читаєте «Конус холоду», на землі під цільовою ділянкою залишається наледь на $180723d, сповільнюючи всіх ворогів у цій зоні на $180724s1%." },
    { en = "When you cast Flash of Light, you have a $h% chance to be able to cast a free Light of Dawn.", ua = "Коли ви творите «Спалах світла», ви маєте $h% шансу отримати змогу сотворити безкоштовне «Світло світанку»." },
    { en = "When you cast Healing Rain, each ally with your Riptide on them is area healed by Tidewaters for $409354s1.", ua = "Коли ви творите «Зцілющий дощ», кожен союзник із вашим «Відпливом» отримує зцілення від «Приливних вод» на $409354s1 по площі." },
    { en = "When you cast Healing Rain, up to $s1 allies within its area are immediately healed for $252154s1.", ua = "Коли ви застосовуєте «Зцілювальний дощ», до $s1 союзників у його зоні миттєво зцілюються на $252154s1." },
    { en = "When you cast Light of Dawn, you have a $h% chance to also be able to cast a free Flash of Light.", ua = "Коли ви творите Світло світанку, ви маєте $h% шанс також безкоштовно застосувати Спалах світла." },
    { en = "When you cast Power Word: Radiance, the damage of your next Penance is increased by $252848s1%.", ua = "Коли ви творите Слово Сили: Сяйво, шкода вашої наступної Покути підвищується на $252848s1%." },
    { en = "When you cast Prayer of Mending, the initial target is blessed with a Holy Spark increasing the healing done by your next Flash Heal, Heal or Holy Word: Serenity by $131567m1% for $131567d.", ua = "Коли ви творите «Молитву зцілення», початкова ціль благословляється «Священною іскрою», що на $131567d збільшує зцілення від вашого наступного «Спалаху зцілення», «Зцілення» чи «Священного слова: Умиротворення» на $131567m1%." },
    { en = "When you cast Prayer of Mending, there is a $s1% chance its effect is duplicated to another ally.", ua = "Коли ви застосовуєте «Молитву зцілення», є $s1% шанс, що її ефект продублюється на іншого союзника." },
    { en = "When you cast Renewing Mist, you have a $h% chance to send a bolt of healing Chi at all targets affected by Tranquil Mist, healing them for $253581s1.", ua = "Коли ви застосовуєте «Оновлюючий туман», ви маєте $h% шанс послати заряд зцілюючого Ці по всіх цілях під дією «Спокійного туману», зцілюючи їх на $253581s1." },
    { en = "When you cast Starsurge or Starfall, the damage of your Moonfire and Sunfire spells is increased by $252767s1% for $252767d.", ua = "Коли ви застосовуєте «Зоряний сплеск» або «Зорепад», шкода ваших закляттів «Місячний вогонь» та «Сонячний вогонь» збільшена на $252767s1% протягом $252767d." },
    { en = "When you cast Unstable Affliction or Seed of Corruption, all targets within $256807A1 yards suffering from your Agony take $252938s1% increased damage from your Corruption$?s63106[, Siphon Life,][] and Agony for $252938d.", ua = "Коли ви створюєте «Нестабільну недугу» чи «Насіння псування», усі цілі в межах $256807A1 ярдів, що потерпають від вашої «Агонії», отримують на $252938s1% більше шкоди від вашого «Псування»$?s63106[, «Викачування життя»][] й «Агонії» протягом $252938d." },
    { en = "When you cast Wild Growth, you have a $h% chance to cause Ysera's Gift to heal a target ${$253434m1*-5}% more frequently for $253434d.", ua = "Коли ви застосовуєте «Буйний ріст», ви маєте $h% шанс змусити «Дар Ісери» зцілювати ціль на ${$253434m1*-5}% частіше протягом $253434d." },
    { en = "When you cast a Healing Wave or Lesser Healing Wave, there is a 25% chance the target also receives a free Lightning Shield that causes $23552s1 Nature damage to attacker on hit.", ua = "Коли ви творите Хвилю зцілення або Меншу хвилю зцілення, є 25% шанс, що ціль також отримає безкоштовний Блискавичний щит, який завдає $23552s1 шкоди природи нападнику при влученні." },
    { en = "When you consume Apex Predator's Craving, become a Big Winner, dealing $1217245s2 Physical damage to Apex Predator's primary target and increasing the damage of your periodic effects by $1217245s1% for $1217245d.", ua = "Коли ви споживаєте «Жагу верховного хижака», ви стаєте Великим переможцем, завдаючи $1217245s2 фізичної шкоди головній цілі верховного хижака й збільшуючи шкоду ваших періодичних ефектів на $1217245s1% протягом $1217245d." },
    { en = "When you consume Brain Freeze, the damage of your next Ice Lance is increased by $253257s1%.", ua = "Коли ви витрачаєте «Крижаний розум», шкода вашого наступного «Крижаного списа» підвищується на $253257s1%." },
    { en = "When you consume Hot Streak, your Pyroblast target has a $171170s1% increased chance to be critically hit by your Fireball spell for $171170d.", ua = "Коли ви витрачаєте «Гарячу серію», ціль вашого «Піровибуху» протягом $171170d має на $171170s1% більший шанс отримати критичний удар від вашого закляття «Вогняна куля»." },
    { en = "When you consume Surge of Mist, your healing done is increased by $247891s1% for $247891d.", ua = "Коли ви споживаєте Приплив Туману, ваше зцілення підвищується на $247891s1% на $247891d." },
    { en = "When you consume a Soul Fragment, all enemies within $246115A1 yards deal $246115s1% less damage to you for $246115d.", ua = "Коли ви поглинаєте Уламок Душі, усі вороги в межах $246115A1 ярдів завдають вам на $246115s1% менше шкоди на $246115d." },
    { en = "When you consume more than $s1 Maelstrom on Earth Shock, you automatically gain Lava Surge.", ua = "Коли ви витрачаєте понад $s1 Виру на «Земний шок», ви автоматично отримуєте «Приплив лави»." },
    { en = "When you critically hit with Marked Shot, you have a $h% chance to gain a Rapid Fire effect increasing haste for $188202d sec.", ua = "Коли ви завдаєте критичного удару «Позначеним пострілом», ви маєте $h% шанс отримати ефект «Швидкий вогонь», що збільшує поспіх на $188202d с." },
    { en = "When you critically hit with Obliterate you gain $187893m1% haste for $187893d. When you critically hit with Frost Strike, your critical damage is increased by $187894m1% for $187894d.", ua = "Коли ви завдаєте критичного удару «Знищенням», ви отримуєте $187893m1% поспіху протягом $187893d. Коли ви завдаєте критичного удару «Крижаним ударом», ваша критична шкода підвищується на $187894m1% протягом $187894d." },
    { en = "When you deal Frost damage, you have a chance to release a barrage of icy spikes at your target dealing ${$253590sw1*3} Frost damage.", ua = "Коли ви завдаєте шкоди Морозом, ви маєте шанс випустити шквал крижаних шпичаків по вашій цілі, завдаючи ${$253590sw1*3} шкоди Морозом." },
    { en = "When you dispel a harmful Magic or Curse effect from an ally, they gain $171382s1 Versatility for $171382d.", ua = "Коли ви розвіюєте шкідливий ефект Магії або Прокляття із союзника, він отримує $171382s1 Універсальності протягом $171382d." },
    { en = "When you enter Eclipse, your next Starsurge or Starfall costs ${-$394414s1/10} less Astral Power and deals $394414s2% increased damage.", ua = "Коли ви входите в «Затемнення», ваш наступний «Зоряний сплеск» чи «Зорепад» коштує на ${-$394414s1/10} менше Астральної сили й завдає на $394414s2% більше шкоди." },
    { en = "When you gain Clearcasting from your Omen of Clarity talent, you deal $70721s1% additional Nature and Arcane damage for $70721d.", ua = "Коли ви отримуєте «Ясне чаклунство» від таланту «Знамення ясності», ви завдаєте на $70721s1% більше шкоди Природою та Арканою протягом $70721d." },
    { en = "When you gain Tidal Waves, you have a $h% chance to reduce the mana cost of Chain Heal by $167703s1% for $167703d.", ua = "Коли ви отримуєте Припливні хвилі, ви маєте $h% шанс зменшити витрату мани Ланцюгового зцілення на $167703s1% на $167703d." },
    { en = "When you gain a stack of |cFFFFFFFFWinning Streak!|r you have an even chance to either cause your next Bloodthirst to deal $1216565s1% increased damage and have $1216565s2% increased chance to critically strike or cause your next Raging Blow to deal $1216569s1% increased damage and generate ${$1216569s2/10} additional Rage.", ua = "Коли ви отримуєте заряд |cFFFFFFFFПереможної серії!|r, ви маєте рівний шанс або зробити так, що ваша наступна «Спрага крові» завдасть на $1216565s1% більше шкоди й матиме на $1216565s2% більший шанс критичного удару, або зробити так, що ваш наступний «Лютий удар» завдасть на $1216569s1% більше шкоди й породить ${$1216569s2/10} додаткової Люті." },
    { en = "When you gain the Blackout Kick! effect, the damage of your next Blackout Kick is increased by $s1%.", ua = "Коли ви отримуєте ефект «Приголомшливий удар!», шкоду вашого наступного «Приголомшливого удару» збільшено на $s1%." },
    { en = "When you gain |cFFFFFFFF Luck of the Draw!|r, your next $1217999U casts of Blackout Kick deal $1217999s2% increased damage and incur a ${$1217999s1/1000}.1 sec reduced cooldown.", ua = "Коли ви отримуєте |cFFFFFFFF Удачу жеребу!|r, ваші наступні $1217999U застосування «Приголомшливого удару» завдають на $1217999s2% більше шкоди й мають зменшене на ${$1217999s1/1000}.1 с відновлення." },
    { en = "When you generate a combo point from Revealing Strike's effect, Honor Among Thieves, or Seal Fate, your next combo point generating ability has its energy cost reduced by $?s53[2]?s111240[6][15]. Stacks up to $145193u times.", ua = "Коли ви генеруєте очко комбо за допомогою ефекту «Викривального удару», «Честі серед злодіїв» чи «Печатки долі», ваша наступна здібність, що генерує очки комбо, має вартість енергії, зменшену на $?s53[2]?s111240[6][15]. Накопичується до $145193u разів." },
    { en = "When you generate an Arcane Charge, you have a $h% chance to increase your haste by $253299s1% for $253299d.", ua = "Коли ви створюєте Арканний заряд, ви маєте $h% шанс збільшити ваш Поспіх на $253299s1% на $253299d." },
    { en = "When you generate an Arcane Charge, you have a chance to increase the number of missiles your next Arcane Missiles will fire by $s1.", ua = "Коли ви створюєте Арканний заряд, ви маєте шанс збільшити кількість снарядів, які випустять ваші наступні Арканні снаряди, на $s1." },
    { en = "When you have Rime active, your next Howling Blast will increase Frost damage taken on all targets by $166057s1% for $166057d.", ua = "Поки у вас активний «Іній», ваш наступний «Виючий вибух» збільшить отримувану шкоду Морозом усіма цілями на $166057s1% на $166057d." },
    { en = "When you heal with Enveloping Mist or Vivify, $m1% of the heal is also applied to targets with your Extend Life effect.", ua = "Коли ви зцілюєте «Огортаючим туманом» або «Оживленням», $m1% зцілення також застосовується до цілей з вашим ефектом «Продовження життя»." },
    { en = "When you hit a target with Lacerate, your critical strike damage is increased by $167165s1% for $167165d.", ua = "Коли ви влучаєте в ціль «Роздиранням», ваша шкода критичного удару збільшується на $167165s1% протягом $167165d." },
    { en = "When you hit a |cFFFFFFFFJackpot!|r your damage is increased by $1219035s1% for $1219035d. If you would gain |cFFFFFFFFJackpot!|r from Combustion the duration is increased by $s2%.", ua = "Коли ви влучаєте у |cFFFFFFFFДжекпот!|r, ваша шкода зростає на $1219035s1% на $1219035d. Якщо ви мали б отримати |cFFFFFFFFДжекпот!|r від «Спалення», тривалість збільшується на $s2%." },
    { en = "When you hit a |cFFFFFFFFJackpot!|r, you also gain $s1 $Lstack:stacks; towards Aether Attunement.", ua = "Коли ви влучаєте в |cFFFFFFFFДжекпот!|r, ви також отримуєте $s1 $Lstack:stacks; до «Настроювання на етер»." },
    { en = "When you kill an enemy that yields experience or honor, gain a Spark of the Primals. Once you reach 5 stacks, your next single target offensive ability will launch a devastating elemental attack.", ua = "Коли ви вбиваєте ворога, що дає досвід або честь, ви отримуєте «Іскру первісних». Щойно ви досягнете 5 накопичень, ваша наступна наступальна здібність по одній цілі запустить нищівну стихійну атаку." },
    { en = "When you lose your |cFFFFFFFFWinning Streak!|r the winds shift into Doom Winds for ${$s1/1000} sec. When Doom Winds deal damage, your next Crash Lightning deals ${$1223332s1}.1% increased damage, up to ${$1223332s1*$1223332u}.1%. This effect can be stored up to $1223410u stacks. Additionally, Crash Lightning deals $s2% more damage to your main target.", ua = "Коли ви втрачаєте свою |cFFFFFFFFПереможну серію!|r, вітри перетворюються на «Вітри погибелі» на ${$s1/1000} с. Коли «Вітри погибелі» завдають шкоди, ваш наступний «Розтрощувальний грім» завдає на ${$1223332s1}.1% більше шкоди, до ${$1223332s1*$1223332u}.1%. Цей ефект може зберігатися до $1223410u зарядів. Крім того, «Розтрощувальний грім» завдає на $s2% більше шкоди вашій головній цілі." },
    { en = "When you lose your |cFFFFFFFFWinning Streak!|r you get the last Holy Power spent back, you cannot lose Holy Power for the next ${$1216837d }.1 sec, and the damage of your Holy Power abilities are increased by $1216837s1%.", ua = "Коли ви втрачаєте свою |cFFFFFFFFПереможну серію!|r, ви повертаєте останню витрачену Святу силу, не можете втрачати Святу силу протягом наступних ${$1216837d }.1 сек, а шкода ваших здібностей на Святій силі збільшується на $1216837s1%." },
    { en = "When you or your pet are below $s1% of maximum health, you gain $171397s1 Versatility.", ua = "Коли ви або ваш улюбленець маєте менше $s1% максимального здоров'я, ви отримуєте $171397s1 Універсальності." },
    { en = "When you parry an attack, the cooldown of Metamorphosis is reduced by ${$m1/1000}.1 sec.  This can only occur once every ${$m2/1000}.1 sec.", ua = "Коли ви відбиваєте атаку, відновлення «Метаморфози» скорочується на ${$m1/1000}.1 с. Це може статися лише раз на ${$m2/1000}.1 с." },
    { en = "When you shift out of Bear Form or Cat Form, your next Healing Touch spell takes ${$37316m1/-1000}.1 fewer sec. to cast.", ua = "Коли ви виходите з «Ведмежої подоби» чи «Котячої подоби», ваше наступне закляття «Зцілювальний доторк» читається на ${$37316m1/-1000}.1 с швидше." },
    { en = "When you shift out of Moonkin Form, your next Healing Touch spell costs $37325s1 less mana.", ua = "Коли ви виходите з подоби Совомедва, ваше наступне закляття «Зцілювальний дотик» коштує на $37325s1 менше Мани." },
    { en = "When you summon a minion, your Haste is increased by $456698s1%, up to ${$456698s1*$456698u}% for $456698d.", ua = "Коли ви прикликаєте слугу, ваш Поспіх збільшується на $456698s1%, до ${$456698s1*$456698u}% протягом $456698d." },
    { en = "When you summon or extend your $?s192249[Storm][Fire] Elemental, your Lightning Bolt, Chain Lightning, $?s454009[Tempest, ][]and Lava Burst deal $1218612s1% increased damage for $1218612d.", ua = "Коли ви призиваєте або подовжуєте свого $?s192249[Штормового][Вогняного] Елементаля, ваші Розряд Блискавки, Ланцюгова Блискавка, $?s454009[Буревій, ][]та Виверження Лави завдають на $1218612s1% більше шкоди на $1218612d." },
    { en = "When you take damage, Mangle and Thrash damage and Rage generation are increased by $408504s2% for $408504d and you heal for $s1% of damage taken over $408504d.", ua = "Коли ви зазнаєте шкоди, шкода від «Роздирання» та «Молотіння» і генерація Люті збільшуються на $408504s2% протягом $408504d, а ви зцілюєтеся на $s1% зазнаної шкоди протягом $408504d." },
    { en = "When you take damage, you have a chance equal to $s1% of your Block chance to cast Judgment at your attacker.", ua = "Коли ви отримуєте шкоду, ви маєте шанс, рівний $s1% вашого шансу блоку, метнути Присуд у свого нападника." },
    { en = "When you take damage, you have a chance equal to $s1% of your Parry chance to lash out, Heart Striking your attacker. Dancing Rune Weapon now summons 2 Rune Weapons.", ua = "Коли ви отримуєте шкоду, ви маєте шанс, рівний $s1% вашого шансу парирування, завдати удару у відповідь, вражаючи нападника Ударом у серце. Танцююча рунічна зброя тепер прикликає 2 Рунічні зброї." },
    { en = "When you trigger a Cacaphonous Chord or Harmonious Chord there is a $s1% chance to trigger the other chord at $s2% of the power.", ua = "Коли ви спрацьовуєте «Какофонічним акордом» чи «Гармонійним акордом», є $s1% шансу спрацювати іншим акордом з $s2% сили." },
    { en = "When you use $?s115008[Chi Torpedo][Roll], the Energy cost of your Tiger Palm is reduced by $165692s1 for $165692d.", ua = "Коли ви застосовуєте $?s115008[«Торпеду ці»][«Перекат»], витрата Енергії вашої «Долоні тигра» зменшена на $165692s1 протягом $165692d." },
    { en = "When you use Avenger's Shield, your block chance is increased by $165447s1% for $165447d.", ua = "Коли ви використовуєте «Щит месника», ваш шанс блокування підвищується на $165447s1% протягом $165447d." },
    { en = "When you use Charge, the critical strike chance of your next Bloodthirst is increased by $165640s1%.", ua = "Коли ви використовуєте «Ривок», шанс критичного удару вашої наступної «Жаги крові» збільшено на $165640s1%." },
    { en = "When you use Charge, the critical strike chance of your next Mortal Strike is increased by $165638s1%.", ua = "Коли ви використовуєте «Ривок», шанс критичного удару вашого наступного «Смертельного удару» збільшується на $165638s1%." },
    { en = "When you use Colossus Smash, your critical damage is increased by $253382s1% for $253382d.", ua = "Коли ви використовуєте «Колосальний удар», ваша критична шкода збільшується на $253382s1% на $253382d." },
    { en = "When you use Envenom, your Deadly and Wound poisons have $252277s1% increased chance to critically strike for $252277d.", ua = "Коли ви використовуєте «Отруєння», ваші «Смертельна отрута» та «Отрута рани» мають на $252277s1% більший шанс критичного удару протягом $252277d." },
    { en = "When you use Exorcism, all damage is increased by $144587s1% for $144587d.", ua = "Коли ви використовуєте «Екзорцизм», уся шкода збільшується на $144587s1% протягом $144587d." },
    { en = "When you use Intercept, the critical strike chance of your next Shield Slam is increased by $165642s1%.", ua = "Коли ви застосовуєте «Перехоплення», шанс критичного удару вашого наступного «Удару щитом» збільшується на $165642s1%." },
    { en = "When you use Judgment, the cost of your next Holy Power spending ability is reduced by $s1.", ua = "Коли ви застосовуєте «Правосуддя», вартість вашого наступного вміння, що витрачає Святу силу, зменшується на $s1." },
    { en = "When you use Kill Command, the cooldown of Aspect of the Wild is reduced by up to ${$m1/1000}.1 sec.", ua = "Коли ви застосовуєте Наказ убити, відновлення Подоби дикої природи зменшується до ${$m1/1000}.1 сек." },
    { en = "When you use Lacerate, you also gain a stack of Mongoose Fury.", ua = "Коли ви застосовуєте «Роздирання», ви також отримуєте стос «Люті мангуста»." },
    { en = "When you use Silence, you gain ${$223687m1/100} Insanity.", ua = "Коли ви застосовуєте «Мовчання», ви отримуєте ${$223687m1/100} Безумства." },
    { en = "When you use Vanish, you gain $s1 Combo Points and the critical strike chance of your next Mutilate or Envenom is increased by $170882s1%.", ua = "Коли ви застосовуєте «Зникнення», ви отримуєте $s1 очок комбо, а шанс критичного удару вашого наступного «Каліцтва» або «Отруєння» збільшується на $170882s1%." },
    { en = "When you use Vanish, you gain $s1 Combo Points and the critical strike chance of your next Saber Slash, Run Through, Between the Eyes, or Ambush is increased by $182304s1%.", ua = "Коли ви застосовуєте «Зникнення», ви отримуєте $s1 очок комбо, а шанс критичного удару вашого наступного «Удару шаблею», «Пробивання», «Між очі» або «Засідки» збільшується на $182304s1%." },
    { en = "When you would gain Vampiric Blood you are infused with Vampiric Strength, granting you $408356s1% Strength for $408356d. Your Heart Strike and Blood Boil extend the duration of Vampiric Strength by ${$s1/1000}.1 sec.", ua = "Коли ви мали б отримати «Вампіричну кров», вас натомість наповнює «Вампірична сила», що дає вам $408356s1% Сили на $408356d. Ваші «Удар у серце» та «Кипіння крові» подовжують тривалість «Вампіричної сили» на ${$s1/1000}.1 с." },
    { en = "When you would lose |cFFFFFFFFWinning Streak!|r, you have a chance to instead gain maximum stacks of |cFFFFFFFFWinning Streak!|r for 4s. These cannot be removed and have $s1% additional effect while immune to removal.", ua = "Коли ви мали б втратити |cFFFFFFFFПереможну серію!|r, ви маєте шанс натомість отримати максимум зарядів |cFFFFFFFFПереможної серії!|r на 4 с. Ці заряди не можна зняти, і поки вони незнімні, їхній ефект на $s1% сильніший." },
    { en = "When your Arcane Shot and Aimed Shot abilities deal damage, you have a $h% chance to gain $71007s1% attack power for $71007d.", ua = "Коли ваші вміння Арканний Постріл і Прицільний Постріл завдають шкоди, ви маєте $h% шанс отримати $71007s1% сили атаки на $71007d." },
    { en = "When your Dancing Rune Weapon expires, you gain $101162s1% additional parry chance for $101162d.", ua = "Коли ваша «Танцююча рунічна зброя» спливає, ви отримуєте додатковий $101162s1% шансу парирування на $101162d." },
    { en = "When your Deadly or Wound poisons critically strike the target, you have a $h% chance to gain $252284s1 Energy.", ua = "Коли ваші «Смертельна отрута» чи «Отрута рани» завдають критичного удару цілі, ви маєте $h% шанс отримати $252284s1 Енергії." },
    { en = "When your Divine Protection expires, you gain an additional $99090s1% parry chance for $99090d .", ua = "Коли ваш «Божественний захист» спливає, ви отримуєте додатковий $99090s1% шансу парирування на $99090d ." },
    { en = "When your Penance spell heals a target you gain $89913s1 Intellect for $89913d, and being in a Chakra state grants you $89912s1 Intellect for the duration of the Chakra.", ua = "Коли ваше закляття Покута зцілює ціль, ви отримуєте $89913s1 Інтелекту на $89913d, а перебування в стані Чакри надає вам $89912s1 Інтелекту на весь час дії Чакри." },
    { en = "When your Power Word: Shield is completely absorbed on an ally, they are granted |cFFFFFFFFInsurance!|r at $s1% effectiveness. Allies with your |cFFFFFFFFInsurance!|r or absorption effects receive $s2% increased healing from you.", ua = "Коли ваше «Слово сили: Щит» повністю поглинуто на союзнику, він отримує |cFFFFFFFFСтраховку!|r з ефективністю $s1%. Союзники з вашою |cFFFFFFFFСтраховкою!|r або ефектами поглинання отримують від вас на $s2% більше зцілення." },
    { en = "When your Renewing Mist heals a target, you have a $h% chance to cast a Mist Wave healing bolt at a nearby low health friendly target.", ua = "Коли ваш Оновлювальний туман зцілює ціль, ви маєте $h% шанс метнути зцілювальний заряд Туманної хвилі в пораненого союзника поблизу." },
    { en = "When your Shadowfiend or Mindbender expires, you gain Premonition, increasing your Critical Strike, Haste, and Mastery ratings by $188779m1 for $188779d.", ua = "Коли ваш «Тіньовий гнобитель» чи «Викривлювач розуму» зникає, ви отримуєте «Передчуття», що збільшує ваші рейтинги Критичного удару, Поспіху та Майстерності на $188779m1 протягом $188779d." },
    { en = "When your Shadowy Apparitions damage their target, they have a $s1% chance to extend the duration of your Shadow Word: Pain and Vampiric Touch, causing each to deal damage one additional time.", ua = "Коли ваші Тіньові примари завдають шкоди своїй цілі, вони мають $s1% шанс продовжити тривалість ваших Тіньового слова: Біль та Вампірського дотику, змушуючи кожне завдати шкоди ще один раз." },
    { en = "When your Shield Block expires, your parry chance is increased by $99243s1% for $99243d.", ua = "Коли ваш «Блок щитом» завершується, ваш шанс парирування збільшується на $99243s1% протягом $99243d." },
    { en = "When your Shield Slam cooldown is reset by Strategist, you gain Expert Strategist, increasing the damage of Shield Slam by $455499s1% and reducing all damage taken by $455499s2% for $455499d.", ua = "Коли час відновлення вашого Удару Щитом скидається Стратегом, ви отримуєте Досвідченого Стратега, що підвищує шкоду Удару Щитом на $455499s1% і зменшує всю дістану шкоду на $455499s2% на $455499d." },
    { en = "When your Vampiric Touch is dispelled, the dispeller is instantly feared in horror for $87204d.", ua = "Коли ваш «Вампіричний дотик» розвіюється, той, хто його розвіяв, миттєво охоплюється жахом на $87204d." },
    { en = "When your Wild Imps cast Felfire Bolt, you have a $m1% chance to summon a Demon from the void to assist you in battle.", ua = "Коли ваші «Дикі бісенята» творять «Стрілу скверновогню», у вас є $m1% шанс прикликати Демона з порожнечі, який допомагатиме вам у бою." },
    { en = "When your bleeds deal damage, they have a chance to grant you Vile Tincture for $458475d, increasing your poison damage by ${$458475s1}.1% per stack (up to $458475u stacks).", ua = "Коли ваші кровотечі завдають шкоди, вони мають шанс дарувати вам Мерзенну настоянку на $458475d, збільшуючи вашу шкоду отрутою на ${$458475s1}.1% за кожен заряд (до $458475u зарядів)." },
    { en = "When your direct damage spells hit an enemy affected by Charring Embers $408673u times the damage of your next $409964u Phoenix Flames is increased by $409964s1% and they refund a charge on use.", ua = "Коли ваші закляття прямої шкоди уражають ворога під дією «Обвуглювального жару» $408673u разів, шкода ваших наступних $409964u «Феніксових полум'їв» підвищується на $409964s1%, і вони повертають заряд під час використання." },
    { en = "When your health drops below 20%, for the next 5 seconds healing spells cast on you help you to Cheat Death, increasing healing done to you by up to $28846s1.", ua = "Коли ваш запас здоров'я падає нижче 20%, протягом наступних 5 секунд зцілювальні закляття, накладені на вас, допомагають вам ошукати смерть, збільшуючи отримуване вами зцілення до $28846s1." },
    { en = "When your weapon poisons deal direct damage, you have a $h% chance to gain Septic Wounds, increasing all Bleed damage done by $394845s1% for $394845d, stacking up to $394845u times.", ua = "Коли отрути вашої зброї завдають прямої шкоди, ви маєте $h% шанс отримати «Гнійні рани», збільшуючи всю завдану шкоду від кровотеч на $394845s1% протягом $394845d, накопичуючись до $394845u разів." },
    { en = "When your |cFFFFFFFFWinning Streak!|r ends you gain $1216556s1% Haste and your Mortal Strike and Cleave damage is increased by $1216556s2% per stack of |cFFFFFFFFWinning Streak!|r you had for $1216556d.", ua = "Коли ваша |cFFFFFFFFПереможна Серія!|r завершується, ви отримуєте $1216556s1% Поспіху, а шкода ваших Смертельного Удару та Розсічення підвищується на $1216556s2% за кожен заряд |cFFFFFFFFПереможної Серії!|r, який ви мали, на $1216556d." },
    { en = "When your|cFFFFFFFF Winning Streak!|r ends, your next $?s259387[Mongoose Bite][Raptor Strike] deals $1216879s1% increased damage and reduces the cooldown of Wildfire Bomb by ${$1216879s2/1000} sec.", ua = "Коли ваша|cFFFFFFFF Переможна серія!|r завершується, ваш наступний $?s259387[«Укус мангуста»][«Удар раптора»] завдає на $1216879s1% більше шкоди й зменшує відновлення «Бомби дикого вогню» на ${$1216879s2/1000} с." },
    { en = "Whenever all your runes are on cooldown, you gain $70657s1% increased damage done with weapons, spells, and abilities for the next $70657d.", ua = "Щоразу, коли всі ваші руни на відновленні, ви отримуєте збільшену на $70657s1% шкоду, завдану зброєю, закляттями та вміннями, на наступні $70657d." },
    { en = "Whenever you are struck by a movement-impairing effect, you will generate $/10;61258s1 Runic Power every $61258t1 sec for $61258d.", ua = "Щоразу, коли на вас діє ефект, що обмежує пересування, ви генеруєте $/10;61258s1 Рунічної сили кожні $61258t1 с протягом $61258d." },
    { en = "Whenever you use Stormstrike, you gain $38430s1 Agility for $38430d.", ua = "Щоразу, коли ви застосовуєте «Штормовий удар», ви отримуєте $38430s1 Спритності на $38430d." },
    { en = "While $?s152277[Ravager][Bladestorm] is active, you automatically cast a total of $?s152277[$s2][$s1] Mortal Strikes at random nearby enemies.", ua = "Поки активний $?s152277[«Спустошувач»][«Клинкова буря»], ви автоматично застосовуєте загалом $?s152277[$s2][$s1] «Смертельних ударів» по випадкових ворогах поблизу." },
    { en = "While $?s157153[Cloudburst Totem][Healing Stream Totem] is active, your chance to critically strike is increased by $394733s1%.", ua = "Поки $?s157153[Тотем Зливи][Тотем Цілющого Потоку] активний, ваш шанс критичного удару підвищений на $394733s1%." },
    { en = "While $?s192249[Storm Elemental][Fire Elemental] is active, your Flame Shock deals $246594s2% increased damage over time and always critically strikes.", ua = "Поки активний $?s192249[Штормовий елементаль][Вогняний елементаль], ваш Вогняний розряд завдає на $246594s2% більше шкоди з часом і завжди завдає критичного удару." },
    { en = "While $@spellname1234996 is empowered, your voidglass shards are $s1% more effective.", ua = "Поки $@spellname1234996 підсилено, ваші уламки скла Порожнечі на $s1% ефективніші." },
    { en = "While Agony, Corruption, and Unstable Affliction are active, your $?s198590[Drain Soul has a $s2% chance][Shadow Bolt has a $s1% chance] to make your next Malefic Rapture cost no Soul Shards and cast instantly.", ua = "Поки активні «Агонія», «Псування» і «Нестійка недуга», ваш $?s198590[«Викрадач душі» має $s2% шансу][«Тіньова стріла» має $s1% шансу] зробити ваше наступне «Лиховісне піднесення» без витрат Уламків душі й миттєвим у прочитанні." },
    { en = "While Arcane Power is active, you can cast Arcane Blast and Arcane Missiles while moving.", ua = "Поки активна Арканна сила, ви можете творити Арканний удар та Арканні снаряди на ходу." },
    { en = "While Battle Cry is active,  your attack speed and critical strike chance increase by $166588s1% every second.", ua = "Поки «Бойовий клич» активний, ваша швидкість атаки та шанс критичного удару підвищуються на $166588s1% щосекунди." },
    { en = "While Berserk is active, special attacks deal an additional $s1% bleed damage to the target over $166638d.", ua = "Поки активний «Берсерк», спеціальні атаки завдають цілі додатково $s1% шкоди кровотечею протягом $166638d." },
    { en = "While Berserked, you radiate $363789s1 Cosmic damage to nearby enemies and heal yourself for $363789s2 every $363793t sec. Deals reduced damage beyond $s1 targets.", ua = "Під час «Берсерка» ви випромінюєте $363789s1 Космічної шкоди по ближніх ворогах і зцілюєте себе на $363789s2 кожні $363793t с. Завдає зменшеної шкоди понад $s1 цілей." },
    { en = "While Bestial Wrath is active, one additional pet is summoned to fight with you.", ua = "Поки активний Звіриний гнів, прикликається один додатковий улюбленець, щоб битися разом з вами." },
    { en = "While Combustion is active your Fire Blast and Phoenix Flames recharge $363508s2% faster.", ua = "Поки активне «Займання», ваші «Вогняний вибух» та «Полум'я фенікса» відновлюються на $363508s2% швидше." },
    { en = "While Dark Soul is active, Haunt's duration is increased by ${$138483m1/1000} sec, Chaos Bolt and Shadowburn consume $s2% less Embers, and abilities cost $s3% less Demonic Fury.", ua = "Поки активна «Темна душа», тривалість «Переслідування» збільшується на ${$138483m1/1000} с, «Стріла хаосу» і «Тіньовий опік» витрачають на $s2% менше жарин, а вміння коштують на $s3% менше Демонічного шалу." },
    { en = "While Dark Soul is active, your damage is increased by $148463s1%.", ua = "Поки активна «Темна душа», ваша шкода збільшена на $148463s1%." },
    { en = "While Demon Spikes is active, your parry chance is increased by an additional $s1%.", ua = "Поки «Демонічні шипи» активні, ваш шанс парирування збільшено на додаткові $s1%." },
    { en = "While Divine Protection is active, $s1% of the damage taken is converted into a heal over time that activates when Divine Protection fades.", ua = "Поки активний Божественний захист, $s1% отриманої шкоди перетворюється на зцілення з часом, яке активується, коли Божественний захист згасає." },
    { en = "While Door of Shadows is off cooldown your $pri is increased by $s3 and its range is increased by $s2 while in outdoor Shadowland zones.", ua = "Поки «Двері тіней» не на відновленні, ваша $pri збільшена на $s3, а їхня дальність збільшена на $s2, поки ви в зонах Тіньокраю просто неба." },
    { en = "While Dragonrage is active you gain Emerald Trance every $424155t3 sec, increasing your damage done by $424155s1%, stacking up to $424155u times.", ua = "Поки активна «Драконяча лють», ви отримуєте «Смарагдовий транс» кожні $424155t3 сек, що збільшує завдану вами шкоду на $424155s1%, накопичуючись до $424155u разів." },
    { en = "While Ebon Might is active, empower spells deal $s1% more damage and cool down $s2% faster.", ua = "Поки активна «Чорна міць», підсилені закляття завдають на $s1% більше шкоди й відновлюються на $s2% швидше." },
    { en = "While Feral Spirits is active, you also turn into a Feral Spirit. While you are transformed, you move $167204s1% faster, and your wolves can proc Windfury.", ua = "Поки активні «Дикі духи», ви також перетворюєтеся на Дикого духа. Поки ви перетворені, ви пересуваєтеся на $167204s1% швидше, а ваші вовки можуть спричиняти «Гнів вітру»." },
    { en = "While Fleshcraft is active your $pri is increased by $s1.", ua = "Поки активне «Плоттворення», ваша $pri збільшена на $s1." },
    { en = "While Frozen Orb is active, you gain Fingers of Frost every ${$m1/1000}.1 sec.", ua = "Поки активна «Крижана сфера», ви отримуєте «Пальці морозу» кожні ${$m1/1000}.1 с." },
    { en = "While Gravewarden is active, the cost of your Death Strike is reduced by $s1 Runic Power.", ua = "Поки активний «Вартовий могил», вартість вашого «Смертельного удару» зменшена на $s1 Рунічної сили." },
    { en = "While Ironfur is active, the cost of Frenzied Regeneration is reduced by $m1%.", ua = "Поки активне «Залізне хутро», вартість «Шаленої регенерації» зменшено на $m1%." },
    { en = "While Pillar of Frost is active, your special attacks trap a soul in your rune weapon. When Pillar of Frost fades, your rune weapon discharges the souls at your current target, dealing $165569sw1 damage per soul.", ua = "Поки активний «Стовп холоду», ваші особливі атаки полонять душу у вашу рунічну зброю. Коли «Стовп холоду» згасає, ваша рунічна зброя вивільняє душі в поточну ціль, завдаючи $165569sw1 шкоди за кожну душу." },
    { en = "While Shadow Dance is active, you cannot lose|cFFFFFFFF Winning Streak!|r, gain an additional stack of|cFFFFFFFF Winning Streak!|r each time you would gain one, and deal an additional $s1% Shadow Damage per|cFFFFFFFF Winning Streak!|r stack.", ua = "Поки активний Тіньовий танець, ви не можете втратити|cFFFFFFFF Переможну серію!|r, отримуєте додатковий заряд|cFFFFFFFF Переможної серії!|r щоразу, коли отримали б один, і завдаєте додаткової $s1% тіньової шкоди за кожен заряд|cFFFFFFFF Переможної серії!|r." },
    { en = "While Survival Instincts is active, $s1% of the direct damage you deal will heal the 2 nearest allies.", ua = "Поки активні «Інстинкти виживання», $s1% прямої шкоди, яку ви завдаєте, зцілюватиме 2 найближчих союзників." },
    { en = "While Trueshot is active, your critical strike damage increases by $165530s1% per second.", ua = "Поки активне «Влучне око», ваша шкода критичного удару збільшується на $165530s1% за секунду." },
    { en = "While Vampiric Blood is active, your Blood Shield cannot be reduced below $s1% of your maximum health.", ua = "Поки активна «Вампірська кров», ваш «Кров'яний щит» не може бути зменшений нижче $s1% вашого максимального здоров'я." },
    { en = "While affected, your Off-Hand strikes sear the wound, dealing $s1 Fire damage.", ua = "Поки триває ефект, удари вашої другої руки припікають рану, завдаючи $s1 шкоди Вогнем." },
    { en = "While at 3 or more stacks of Bastion of Glory, your next $?s114163[Eternal Flame][Word of Glory] will consume no Holy Power and count as if 3 Holy Power were consumed.", ua = "При 3 чи більше зарядах «Бастіону слави» ваше наступне $?s114163[«Вічне полум'я»][«Слово слави»] не витратить Святої сили і зарахується так, ніби витрачено 3 Святої сили." },
    { en = "While channeling Drain Life or Drain Soul on a target afflicted by your Corruption, Unstable Affliction, and Agony, Agony will generate 1 additional Soul Shard.", ua = "Поки ви скеровуєте «Викрадення життя» або «Викрадача душі» на ціль, уражену вашими «Псуванням», «Нестійкою недугою» і «Агонією», «Агонія» генеруватиме 1 додатковий Уламок душі." },
    { en = "While in Ny'alotha, your spells and abilities have a chance to draw an orb of Vita and Void towards you. Collecting the orb increases your $pri by $s1 for $315858d.", ua = "Поки ви в Н'алоті, ваші закляття й здібності мають шанс притягнути до вас сферу Віти й Порожнечі. Збирання сфери збільшує ваш $pri на $s1 протягом $315858d." },
    { en = "While in an Eclipse, the cost of Starsurge and Starfall is reduced by $s2%.", ua = "Під час затемнення вартість «Зоряного сплеску» і «Зорепаду» зменшена на $s2%." },
    { en = "While in combat there is a chance that lightning will strike nearby. Gathering the orb of lightning left behind will infuse you with the Fury of the Stormrook, granting $449440s1 Haste for $449440d.", ua = "Під час бою є шанс, що поблизу вдарить блискавка. Зібравши залишену нею кулю блискавки, ви вбираєте Лють Штормового ворона, отримуючи $449440s1 Поспіху на $449440d." },
    { en = "While not affected by Shield of the Righteous, the effect of Vindicator's Shield is increased by $s1%.", ua = "Поки ви не під дією «Щита праведних», ефект «Щита захисника» збільшено на $s1%." },
    { en = "While you are below 35% health you take $221618s1% reduced damage in outdoor Broken Isles zones.", ua = "Поки ваше здоров'я нижче за 35%, ви отримуєте на $221618s1% менше шкоди на відкритих територіях Розколотих островів." },
    { en = "While you are in Shadowform, your Shadowfiend or Mindbender deals $99155s1% additional damage as Fire damage, and the cooldown on Shadowfiend and Mindbender is reduced by $s2%.", ua = "Поки ви в Тіньовій подобі, ваша Тіньова нечисть чи Спокусник розуму завдає на $99155s1% більше шкоди як вогняна, а час відновлення Тіньової нечисті й Спокусника розуму зменшено на $s2%." },
    { en = "While you are within an empowered Consecration, your abilities have a chance to deal $s1% bonus damage or healing as Fire.", ua = "Поки ви перебуваєте в підсиленому «Освяченні», ваші здібності мають шанс завдати $s1% бонусної шкоди чи зцілення Вогнем." },
    { en = "While you have $s1 or more stacks of Vile Tincture, Garrote, Rupture, and Crimson Tempest deal $458476s1% additional damage.", ua = "Поки у вас $s1 або більше зарядів Мерзенної настоянки, Гаротта, Розрив і Багряна буря завдають на $458476s1% більше шкоди." },
    { en = "While you have Shadow Word: Pain and Vampiric Touch active on the same target you gain Dark Flames, which increases the damage done by Mind Blast by $99158s1%.", ua = "Поки на одній цілі активні ваші «Слово тіні: біль» і «Вампірський дотик», ви отримуєте «Темне полум'я», що збільшує шкоду, завдану «Ударом розуму», на $99158s1%." },
    { en = "While you have any stacks of Maelstrom Weapon, your Lightning Bolt, Chain Lightning, and healing spells deal $105869s1% more healing or damage.", ua = "Поки у вас є будь-які заряди Зброї Виру, ваші Розряд Блискавки, Ланцюгова Блискавка та зцілювальні закляття дають на $105869s1% більше зцілення чи шкоди." },
    { en = "While you have one or more Bone Shield charges, the damage you take is reduced by ${$abs($457468S1)}.1%. Losing a Bone Shield charge has a chance to reduce the damage you take by an additional ${$abs($457473S1)}.1%, up to ${$abs($457473S1)*$457473U}.1% for $457473d.", ua = "Поки у вас є один або більше зарядів Кістяного Щита, дістана вами шкода зменшена на ${$abs($457468S1)}.1%. Втрата заряду Кістяного Щита має шанс зменшити дістану вами шкоду ще на ${$abs($457473S1)}.1%, максимум до ${$abs($457473S1)*$457473U}.1% на $457473d." },
    { en = "While you have |cFFFFFFFF Luck of the Draw!|r Shield of the Righteous refunds $s1-$s2 Holy Power and extends the duration of |cFFFFFFFF Luck of the Draw!|r by ${$s3/1000}.1 sec, up to $1218114d.", ua = "Поки ви маєте |cFFFFFFFF Щасливий випадок!|r, «Щит праведника» повертає $s1-$s2 Святої сили та продовжує тривалість |cFFFFFFFF Щасливого випадку!|r на ${$s3/1000}.1 сек, до $1218114d." },
    { en = "While your $?s192249[Storm Elemental][Fire Elemental] is active, your Lava Burst deals $364523s2% additional damage and you gain Lava Surge every $364523t1 sec.", ua = "Поки ваш $?s192249[Штормовий елементаль][Вогняний елементаль] активний, ваше Виверження лави завдає на $364523s2% більше шкоди, і ви отримуєте Сплеск лави кожні $364523t1 с." },
    { en = "While your Dancing Rune Weapon is active Heart Strike extends the duration of Dancing Rune Weapon by ${$s1/1000}.1 seconds and increases your Strength by $s3%, persisting for $s4 seconds after Dancing Rune Weapon ends.", ua = "Поки активна ваша «Танцівна рунічна зброя», «Удар у серце» продовжує тривалість «Танцівної рунічної зброї» на ${$s1/1000}.1 секунди й збільшує вашу Силу на $s3%, зберігаючись протягом $s4 секунд після завершення «Танцівної рунічної зброї»." },
    { en = "While your Divine Favor talent is active, your healing spells are $71166s1% stronger.", ua = "Поки активний ваш талант «Божественна прихильність», ваші зцілювальні закляття на $71166s1% сильніші." },
    { en = "While your Harmony mastery bonus to periodic healing is active, you gain $90159s1 Intellect.", ua = "Поки активний ваш бонус майстерності Гармонія до періодичного зцілення, ви отримуєте $90159s1 Інтелекту." },
    { en = "While your pet is active, increases attack power by $28758s1 for both you and your pet.", ua = "Поки ваш улюбленець активний, збільшує силу атаки на $28758s1 і вам, і вашому улюбленцю." },
    { en = "While your weapon is imbued with Flametongue Weapon, your attacks also slow the target's movement speed by $147732s1% for $147732d.", ua = "Поки вашу зброю просякнуто «Зброєю вогняного язика», ваші атаки також уповільнюють швидкість руху цілі на $147732s1% протягом $147732d." },
    { en = "Wild Growth cooldown reduced by ${$s1/-1000} sec, and mana cost reduced by $s2%.", ua = "Відновлення «Дикого зростання» зменшено на ${$s1/-1000} сек., а вартість мани зменшено на $s2%." },
    { en = "Wild Growth grants you $232378s1 Mastery for $232378d.", ua = "«Буйний ріст» дає вам $232378s1 до Майстерності на $232378d." },
    { en = "Wild Growth healing increased by $s1%.", ua = "Зцілення від «Дикого розростання» збільшено на $s1%." },
    { en = "Wild Imp damage increased by $s1%. Implosion damage increased by $s2%.", ua = "Шкода від Дикого бісеняти збільшена на $s1%. Шкода від Вибуху збільшена на $s2%." },
    { en = "Wildfire Bomb damage increased by $s1%, and throwing a Wildfire Bomb increases the damage of your next Kill Command by $410147s1%.", ua = "Шкода «Бомби дикого вогню» підвищена на $s1%, а кидок «Бомби дикого вогню» підвищує шкоду вашого наступного «Наказу вбити» на $410147s1%." },
    { en = "Wildfire Bomb damage increased by $s1%.", ua = "Шкоду «Запальної бомби» збільшено на $s1%." },
    { en = "Wildfire Bomb provokes an additional Strike as One at $s1% effectiveness.", ua = "Бомба Дикого Вогню викликає додатковий Удар Заодно з $s1% ефективністю." },
    { en = "Windfury now deals damage $s1 extra times.", ua = "«Гнів вітру» тепер завдає шкоди на $s1 разів більше." },
    { en = "Wrathful Sanction grants you Echoes of Wrath, causing your next Templar's Verdict or Divine Storm to deal damage a second time at $s1% effectiveness. This effect does not consume Judgment.", ua = "«Гнівна кара» дарує вам «Відлуння гніву», через що ваш наступний «Вирок тамплієра» чи «Божественна буря» завдає шкоди вдруге з $s1% ефективністю. Цей ефект не витрачає «Присуд»." },
    { en = "You and your Grove Guardian's Nourishes now heal $s1 additional allies within $423618r yds at $s2% effectiveness.", ua = "Ваші «Живлення» та «Живлення» вашого Вартового гаю тепер зцілюють $s1 додаткових союзників у радіусі $423618r м з $s2% ефективності." },
    { en = "You and your pet share diminishing returns from crowd control effects.", ua = "Ви й ваш улюбленець розділяєте спадну віддачу від ефектів контролю." },
    { en = "You are a party animal! Use your party favors and powers of persuasion to please the partygoers.", ua = "Ви душа компанії! Скористайтеся своїми святковими дарунками й силою переконання, щоб потішити гуляк." },
    { en = "You can Lifebloom two targets at once.", ua = "Ви можете накладати Цвіт життя на дві цілі одночасно." },
    { en = "You gain $186367m1% haste for $186367d when Prayer of Mending bounces. This effect can stack up to $186367u times.", ua = "Ви отримуєте $186367m1% Поспіху на $186367d, коли Молитва зцілення перестрибує. Цей ефект може накопичуватися до $186367u разів." },
    { en = "You gain $212236s1% increased chance to critically block while Shield Block is active.", ua = "Ви отримуєте на $212236s1% підвищений шанс критично блокувати, поки Блок Щитом активний." },
    { en = "You gain $s1% additional haste from your Flurry ability.", ua = "Ви отримуєте на $s1% більше поспіху від вашої здібності Шквал." },
    { en = "You gain 1 Holy Power for each $138250s1% of your health taken as damage while Divine Protection is active.", ua = "Ви отримуєте 1 Святу силу за кожні $138250s1% вашого здоров'я, втраченого як шкода, поки активний «Божественний захист»." },
    { en = "You gain Vindicator's Shield, increasing your block chance by $s1%.", ua = "Ви отримуєте «Щит захисника», що підвищує ваш шанс блокування на $s1%." },
    { en = "You gain a charge of Holy Power whenever you take direct damage.  This effect cannot occur more than once every $s2 seconds.", ua = "Ви отримуєте заряд Святої сили щоразу, коли отримуєте пряму шкоду.  Цей ефект не може спрацьовувати частіше ніж раз на $s2 с." },
    { en = "You gain an additional ${$37521m1/10} rage each time one of your attacks is parried or dodged.", ua = "Ви отримуєте додаткові ${$37521m1/10} гніву щоразу, коли одну з ваших атак парирують або від неї ухиляються." },
    { en = "You generate $138225s1% more Rage from your attacks while Enrage is active.", ua = "Ви породжуєте на $138225s1% більше Гніву від своїх атак, поки активний «Шал»." },
    { en = "You have a $h% chance from your autoshots to make your next shot or Kill Command cost no focus.", ua = "У вас є $h% шансу від автопострілів зробити ваш наступний постріл або «Наказ вбити» без витрати зосередженості." },
    { en = "You have a $s1% chance for Shadow Bolt or Demonwrath to generate 1 additional Soul Shard.", ua = "У вас є $s1% шанс, що «Тіньова стріла» або «Демонічний гнів» згенерують 1 додатковий Уламок душі." },
    { en = "You have a $s1% chance to refund a Soul Shard after spending a Soul Shard.", ua = "Ви маєте $s1% шанс повернути Уламок душі після витрачання Уламка душі." },
    { en = "You have a $s1% chance whenever your Maelstrom Weapon effect occurs to Electrocute all nearby enemies within $189509A1 yards for $189509m1 Nature damage.", ua = "Щоразу, коли спрацьовує ваш ефект «Зброя виру», ви маєте $s1% шанс уразити струмом усіх ворогів поблизу в межах $189509A1 ярдів, завдаючи $189509m1 шкоди природою." },
    { en = "You have a chance each time you are hit to gain $37526s1 haste for $37526d.", ua = "Ви маєте шанс щоразу, коли вас вражають, отримати $37526s1 Поспіху протягом $37526d." },
    { en = "You have a chance each time you parry to gain Blade Turning, absorbing $37515s1 damage for $37515d.", ua = "Щоразу, коли ви парируєте, ви маєте шанс отримати «Відведення клинка», що поглинає $37515s1 шкоди на $37515d." },
    { en = "You have a chance to summon a Burning Treant to assist you in battle for $99035d when you cast Wrath or Starfire.", ua = "У вас є шанс прикликати Палаючого трента, що допоможе вам у бою на $99035d, коли ви творите «Гнів» або «Зоряний вогонь»." },
    { en = "You have a chance to summon a Mirror Image to assist you in battle for $99063d when you cast Frostbolt, Fireball, Frostfire Bolt, or Arcane Blast.", ua = "Ви маєте шанс призвати Дзеркальну Подобу, що допоможе вам у бою протягом $99063d, коли ви творите Морозний Спалах, Вогняну Кулю, Морозновогняний Спалах або Арканний Вибух." },
    { en = "You have a chance when being hit to increase your dodge chance by $179129s1% for $179129d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "У вас є шанс під час отримання удару збільшити ваш шанс ухилення на $179129s1% протягом $179129d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "You have a chance when taking damage to gain Fel Bulwark, absorbing $187145m1 damage for $187145d.", ua = "Отримуючи шкоду, ви маєте шанс здобути «Оплот Скверни», що поглинає $187145m1 шкоди протягом $187145d." },
    { en = "You have a chance when taking damage to reduce all damage taken by $179144s1% for $179144d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Дістаючи шкоди, ви маєте шанс зменшити всю дістану шкоду на $179144s1% на $179144d.  (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "You have a chance when you cast Chain Heal to cast a second Chain Heal at one of the targets healed.", ua = "Коли ви творите «Ланцюгове зцілення», є шанс сотворити друге «Ланцюгове зцілення» по одній із зцілених цілей." },
    { en = "You have a chance when you cast a helpful spell to summon a Cauterizing Flame at the target's location.  Each sec the Cauterizing Flame will heal an injured party member within 40 yards for $99152s1.  Lasts $99136d.", ua = "У вас є шанс, творячи корисне закляття, прикликати Припалююче полум'я в місці цілі.  Щосекунди Припалююче полум'я зцілюватиме пораненого учасника групи в межах 40 м на $99152s1.  Триває $99136d." },
    { en = "You have a chance whenever you deal ranged damage to apply an Expose Weakness effect to the target. Expose Weakness increases the ranged attack power of all attackers against that target by $23577s1 for $23577d.", ua = "Ви маєте шанс щоразу, коли завдаєте шкоди в дальньому бою, накласти на ціль ефект «Оголення слабкості». «Оголення слабкості» підвищує силу атаки в дальньому бою всіх нападників проти цієї цілі на $23577s1 на $23577d." },
    { en = "You have a chance while Roll the Bones is active to gain the Adrenaline Rush effect for $186286d.", ua = "Під час дії «Кидка костей» ви маєте шанс отримати ефект «Приплив адреналіну» на $186286d." },
    { en = "You heal for $s1% of all damage blocked with a shield and $s1% of all damage absorbed by Shield Barrier.", ua = "Ви зцілюєтеся на $s1% усієї шкоди, заблокованої щитом, та $s1% усієї шкоди, поглинутої «Бар'єром щита»." },
    { en = "You now generate Rage from taking damage.", ua = "Тепер ви генеруєте Лють, отримуючи шкоду." },
    { en = "You take ${$m1/-100}% less damage from players.", ua = "Ви отримуєте на ${$m1/-100}% менше шкоди від гравців." },
