    { en = "Your Water Shield ability grants an additional $s1 mana each time it triggers and an additional $s2 mana per 5 sec.", ua = "Ваша здібність «Водяний щит» надає додатково $s1 мани щоразу, коли спрацьовує, та додатково $s2 мани кожні 5 с." },
    { en = "Your Water Shield is $s1% stronger.", ua = "Ваш «Водяний щит» на $s1% сильніший." },
