    { en = "Your abilities have a chance to begin a |cFFFFFFFFWinning Streak!|r, increasing the damage of Overpower by $1216552s1%, stacking up to $1216552U times. \nOverpower has a $1216552H% chance to end your |cFFFFFFFFWinning Streak!|r", ua = "Ваші здібності мають шанс розпочати |cFFFFFFFFПереможну серію!|r, збільшуючи шкоду від Здолання на $1216552s1%, накопичуючись до $1216552U разів. \nЗдолання має $1216552H% шанс завершити вашу |cFFFFFFFFПереможну серію!|r" },
    { en = "Your abilities have a chance to start a |cFFFFFFFFWinning Streak!|r, increasing the damage of Rampage by $1216561s1%, stacking up to $1216561U times.\nRampage has a $1216561H% chance to end your |cFFFFFFFFWinning Streak!|r", ua = "Ваші здібності мають шанс розпочати |cFFFFFFFFПереможну серію!|r, збільшуючи шкоду від Буйства на $1216561s1%, накопичуючись до $1216561U разів.\nБуйство має $1216561H% шанс завершити вашу |cFFFFFFFFПереможну серію!|r" },
    { en = "Your abilities have an additional $s1% chance to trigger Gore.", ua = "Ваші вміння мають додатковий $s1% шансу запустити «Проштрикування»." },
    { en = "Your allies can use your Demonic Gateway again $s1 sec sooner.", ua = "Ваші союзники можуть скористатися вашими Демонічними Вратами знову на $s1 сек раніше." },
    { en = "Your attack speed is increased by $s1%, and Crimson Scourge's chance to occur is increased by an additional $s2%.", ua = "Ваша швидкість атаки збільшена на $s1%, а шанс спрацювання Багряної погибелі збільшено ще на $s2%." },
    { en = "Your attacks against targets afflicted by Breath of Fire have a chance to deal $s1% extra damage as Shadowflame, and each Celestial Brew also grants a Stagger absorb for $s2% of the Shadowflame damage you have dealt, causing damage delayed by Stagger to instead be prevented.", ua = "Ваші атаки по цілях, вражених «Подихом вогню», мають шанс завдати на $s1% більше шкоди у вигляді Тіньового полум'я, і кожен «Небесний трунок» також дарує поглинання «Похитування» на $s2% Тіньовополум'яної шкоди, яку ви завдали, через що шкода, відкладена «Похитуванням», натомість запобігається." },
    { en = "Your attacks have a chance to grant you $37612s1 Agility for $37612d.", ua = "Ваші атаки мають шанс дарувати вам $37612s1 Спритності протягом $37612d." },
    { en = "Your attacks have a chance to grant you $91965s1 Strength for $91965d.", ua = "Ваші атаки мають шанс дарувати вам $91965s1 Сили протягом $91965d." },
    { en = "Your attacks have a chance to increase your attack speed by $187147m1% for $187147d. However, every $187151m2 sec the effect is diminished.", ua = "Ваші атаки мають шанс збільшити вашу швидкість атаки на $187147m1% протягом $187147d. Проте кожні $187151m2 с ефект слабшає." },
    { en = "Your attacks have a chance to increase your damage dealt by $179141s1% for $179141d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс збільшити завдану вами шкоду на $179141s1% на $179141d.  (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your attacks have a chance to make your next finishing move cost no energy.", ua = "Ваші атаки мають шанс зробити ваш наступний завершальний прийом без витрати енергії." },
    { en = "Your attacks have a chance to raise the spirit of a fallen Zandalari as your Death Knight minion for $138342d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс підняти дух полеглого зандаларі як вашого прислужника Лицаря смерті на $138342d.  (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your attacks with Mangle, Maul, and Shred deal $s1% additional damage as Fire damage over $99002d.", ua = "Ваші атаки «Понівеченням», «Тереблінням» і «Шматуванням» завдають $s1% додаткової шкоди як шкоди Вогнем протягом $99002d." },
