    { en = "Your critical heals from Healing Wave, Healing Surge, and Chain Heal reduce the cast time of your next Healing Wave spell by ${$39950m1/-1000}.2 sec for $39950d.  This effect cannot occur more than once per minute.", ua = "Ваші критичні зцілення від «Хвилі зцілення», «Припливу зцілення» та «Ланцюгового зцілення» зменшують час прочитання вашого наступного «Хвилі зцілення» на ${$39950m1/-1000}.2 с протягом $39950d.  Цей ефект не може спрацьовувати частіше ніж раз на хвилину." },
    { en = "Your critical heals have ${200+$s1}% effectiveness instead of the usual 200%.", ua = "Ваші критичні зцілення мають ${200+$s1}% ефективності замість звичайних 200%." },
    { en = "Your critical strikes deal ${$s1+200}% damage instead of the usual 200%.", ua = "Ваші критичні удари завдають ${$s1+200}% шкоди замість звичних 200%." },
    { en = "Your critical strikes from Lightning Bolt cause the target to take nature damage equal to $s1% of the Lightning Bolt's damage over $64930d.", ua = "Ваші критичні удари від «Блискавичної стріли» змушують ціль отримувати шкоду природою, що дорівнює $s1% шкоди «Блискавичної стріли», протягом $64930d." },
    { en = "Your critical strikes from Starfire and Wrath cause the target to languish for an additional $70723s1% of your spell's damage over $71023d.", ua = "Ваші критичні удари від «Зоряного полум'я» та «Гніву» змушують ціль страждати, завдаючи додатково $70723s1% шкоди вашого закляття протягом $71023d." },
    { en = "Your damage done is increased by $s1%.", ua = "Шкода, яку ви завдаєте, збільшена на $s1%." },
    { en = "Your damage is increased by $1301768s3% while in any Eclipse. This bonus wanes to $1301768s4% at the midpoint of the Eclipse, then waxes back to $1301768s3% at the end.", ua = "Ваша шкода збільшена на $1301768s3% під час будь-якого Затемнення. Цей бонус спадає до $1301768s4% посередині Затемнення, а потім знову зростає до $1301768s3% наприкінці." },
