    { en = "Your damage spells have a chance to cause your target to take up to $28772s1 increased damage from subsequent spells.", ua = "Ваші закляття шкоди мають шанс змусити вашу ціль отримувати до $28772s1 збільшеної шкоди від наступних заклять." },
    { en = "Your damage spells have a chance to displace you, causing the next spell cast to generate no threat.", ua = "Ваші шкідливі закляття мають шанс змістити вас, унаслідок чого ваше наступне сотворене закляття не генерує загрози." },
    { en = "Your damaging Holy Power abilities deal $s1% increased damage.", ua = "Ваші шкідливі здібності Священної сили завдають на $s1% більше шкоди." },
