    { en = "Your damaging spells and abilities have a chance to poison your target, dealing $274220s1 damage every $274220T0 seconds.", ua = "Ваші закляття й здібності, що завдають шкоди, мають шанс отруїти вашу ціль, завдаючи $274220s1 шкоди кожні $274220T0 секунд." },
    { en = "Your damaging spells and abilities have a chance to send you into a wild frenzy, granting you $274240s0 Strength for $274240d.", ua = "Ваші шкідливі закляття та здібності мають шанс увести вас у дике шаленство, надаючи $274240s0 Сили на $274240d." },
    { en = "Your damaging spells and abilities have a chance to shock your target, dealing $274226s1 Nature damage.", ua = "Ваші шкідливі закляття та здібності мають шанс уразити ціль розрядом, завдаючи $274226s1 шкоди Природою." },
