    { en = "Your damaging spells have an $h% chance to fire a chaotic flame towards your target, dealing $187773m1 Chaos damage to all enemies it passes through.", ua = "Ваші шкодочинні закляття мають $h% шансу випустити хаотичне полум'я в напрямку вашої цілі, завдаючи $187773m1 шкоди Хаосом усім ворогам, крізь яких воно проходить." },
    { en = "Your direct damage spells have a chance to engulf the target in Fel Chaos for $m1 sec.", ua = "Ваші закляття прямої шкоди мають шанс огорнути ціль «Скверним хаосом» на $m1 с." },
    { en = "Your direct damage spells have a chance to imbue you with Nature's Fury for $179119d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші закляття прямої шкоди мають шанс наповнити вас «Люттю природи» протягом $179119d.  (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your direct heals have a chance to cause Cauterizing Heal. Your direct damage spells have a chance to cause Searing Flame.", ua = "Ваше пряме зцілення має шанс викликати Припікальне Зцілення. Ваші закляття прямої шкоди мають шанс викликати Пекуче Полум'я." },
    { en = "Your finishing moves have a $h% chance to grant you a combo point.", ua = "Ваші добивальні прийоми мають $h% шанс дати вам очко комбо." },
    { en = "Your finishing moves have a $s2% chance per combo point to cast Shadowstrike at up to $s3 enemies within 15 yards.", ua = "Ваші добивальні прийоми мають $s2% шанс за очко комбо метнути Тіньовий удар у до $s3 ворогів у межах 15 метрів." },
    { en = "Your finishing moves have a ${$h/5}% chance per combo point to generate 5 combo points and cause your next Run Through to consume no Energy.", ua = "Ваші добивальні прийоми мають ${$h/5}% шанс за очко комбо згенерувати 5 очок комбо і зробити так, що ваш наступний «Наскрізний удар» не витратить Енергії." },
    { en = "Your finishing moves have a 20% chance per combo point to extend the duration of Berserk by $s1 sec and when your Barkskin ability expires you gain an additional $99011s1% chance to dodge for $99011d.", ua = "Ваші добивальні прийоми мають 20% шансу за кожне очко комбо продовжити тривалість «Берсерка» на $s1 сек, а коли вміння «Кора» завершується, ви отримуєте додаткові $99011s1% шансу ухилитися на $99011d." },
    { en = "Your finishing moves have a chance to increase your Haste by $221639s1 for $221639d.", ua = "Ваші добивальні прийоми мають шанс збільшити ваш Поспіх на $221639s1 протягом $221639d." },
    { en = "Your finishing moves have a chance to increase your Haste by $221663s1 for $221663d.", ua = "Ваші завершальні прийоми мають шанс підвищити ваш Поспіх на $221663s1 на $221663d." },
