    { en = "Your spells and abilities have a chance to activate a |cFFFFFFFFWinning Streak!|r, increasing the damage of your Death Coil and Epidemic by ${$s2/10}.1%, stacking up to $1216813u times. Death Coil and Epidemic have a $s1% chance to remove|cFFFFFFFF Winning Streak!|r", ua = "Ваші закляття і вміння мають шанс активувати |cFFFFFFFFСмугу перемог!|r, збільшуючи шкоду ваших «Оболонки смерті» і «Епідемії» на ${$s2/10}.1%, стосуючись до $1216813u разів. «Оболонка смерті» і «Епідемія» мають $s1% шансу зняти|cFFFFFFFF Смугу перемог!|r" },
    { en = "Your spells and abilities have a chance to activate a|cFFFFFFFF Winning Streak!|r increasing the damage of your Blade Dance and Chaos Strike by $1217011s1% stacking up to $1217011u times. Blade Dance and Chaos Strike have a $s1% chance to remove|cFFFFFFFF Winning Streak!|r", ua = "Ваші закляття та вміння мають шанс активувати|cFFFFFFFF Переможну Серію!|r, підвищуючи шкоду ваших Танцю Клинків і Хаосного Удару на $1217011s1%, накопичуючись до $1217011u разів. Танець Клинків і Хаосний Удар мають $s1% шанс зняти|cFFFFFFFF Переможну Серію!|r" },
    { en = "Your spells and abilities have a chance to activate a|cFFFFFFFF Winning Streak!|r increasing the damage of your Dispatch by $1217078s1% stacking up to $s2 times. Dispatch has a $s1% chance to remove|cFFFFFFFF Winning Streak!|r", ua = "Ваші закляття та здібності мають шанс активувати|cFFFFFFFF Переможну серію!|r, що збільшує шкоду вашої «Розправи» на $1217078s1%, накопичуючись до $s2 разів. «Розправа» має $s1% шанс зняти|cFFFFFFFF Переможну серію!|r" },
    { en = "Your spells and abilities have a chance to activate a|cFFFFFFFF Winning Streak!|r increasing the damage of your Envenom, Rupture, and Crimson Tempest by $1218439s1% stacking up to $1218439u times. Envenom, Rupture, and Crimson Tempest have a $s1% chance to remove|cFFFFFFFF Winning Streak!|r", ua = "Ваші закляття та здібності мають шанс активувати|cFFFFFFFF Переможну серію!|r, що збільшує шкоду ваших «Отруєння», «Розриву» та «Багряної бурі» на $1218439s1%, накопичуючись до $1218439u разів. «Отруєння», «Розрив» і «Багряна буря» мають $s1% шанс зняти|cFFFFFFFF Переможну серію!|r" },
    { en = "Your spells and abilities have a chance to activate a|cFFFFFFFF Winning Streak!|r increasing the damage of your Eviscerate, Secret Technique, and Black Powder by $1218143s1% stacking up to $1218143u times. Eviscerate, Secret Technique, and Black Powder have a $s1% chance to remove|cFFFFFFFF Winning Streak!|r", ua = "Ваші закляття та здібності мають шанс активувати|cFFFFFFFF Переможну серію!|r, що підвищує шкоду «Потрошіння», «Таємної техніки» та «Чорного пороху» на $1218143s1%, накопичуючись до $1218143u разів. «Потрошіння», «Таємна техніка» та «Чорний порох» мають $s1% шанс зняти|cFFFFFFFF Переможну серію!|r" },
    { en = "Your spells and abilities have a chance to activate a|cFFFFFFFF Winning Streak!|r increasing the damage of your Stormstrike, Lava Lash and Doom Winds by $1218616s1%, up to ${$1218616s1*$1218616u}%. Maelstrom Weapon spenders have a ${$s1/10}.1% chance to remove |cFFFFFFFFWinning Streak!|r per Maelstrom Weapon spent.", ua = "Ваші закляття та здібності мають шанс активувати|cFFFFFFFF Переможну серію!|r, що збільшує шкоду ваших «Штормового удару», «Лавового батога» та «Вітрів загибелі» на $1218616s1%, до ${$1218616s1*$1218616u}%. Здібності, що витрачають «Зброю виру», мають ${$s1/10}.1% шанс зняти |cFFFFFFFFПереможну серію!|r за кожну витрачену «Зброю виру»." },
    { en = "Your spells and abilities have a chance to activate a|cFFFFFFFF Winning Streak!|r increasing the damage of your Templar's Verdict and Divine Storm by $1216828s1% stacking up to $1216828u times. Spending Holy Power on damaging abilities has a $1216828s2% chance to remove |cFFFFFFFFWinning Streak!|r", ua = "Ваші закляття та вміння мають шанс активувати|cFFFFFFFF Переможну Серію!|r, підвищуючи шкоду ваших Вироку Тамплієра та Божественної Бурі на $1216828s1%, накопичуючись до $1216828u разів. Витрата Святої Сили на шкодочинні вміння має $1216828s2% шанс зняти |cFFFFFFFFПереможну Серію!|r" },
    { en = "Your spells and abilities have a chance to activate a|cFFFFFFFF Winning Streak!|r increasing the damage of your Wildfire Bomb by $1216874s1% stacking up to $1216874U times. \nWildfire Bomb has a $1216874H% chance to end your|cFFFFFFFF Winning Streak!|r", ua = "Ваші закляття та здібності мають шанс активувати|cFFFFFFFF Переможну серію!|r, збільшуючи шкоду вашої Бомби пожежі на $1216874s1%, накопичуючись до $1216874U разів. \nБомба пожежі має $1216874H% шанс завершити вашу|cFFFFFFFF Переможну серію!|r" },
    { en = "Your spells and abilities have a chance to activate a|cFFFFFFFF Winning Streak!|r, increasing the damage of your Ferocious Bite, Rip, and Primal Wrath by $1217236s1%, stacking up to $1217236u times. Ferocious Bite, Rip, and Primal Wrath have a $s1% chance to remove|cFFFFFFFF Winning Streak!|r. Free Ferocious Bites are exempt from this chance.", ua = "Ваші закляття та здібності мають шанс активувати|cFFFFFFFF Переможну серію!|r, що підвищує шкоду «Лютого укусу», «Роздирання» та «Первинного гніву» на $1217236s1%, накопичуючись до $1217236u разів. «Лютий укус», «Роздирання» та «Первинний гнів» мають $s1% шанс зняти|cFFFFFFFF Переможну серію!|r. Безкоштовні «Люті укуси» не підпадають під цей шанс." },
    { en = "Your spells and abilities have a chance to activate a|cFFFFFFFF Winning Streak!|r, increasing the damage of your Frost Strike and Glacial Advance by $1217897s1%, stacking up to $1217897u times. Frost Strike and Glacial Advance have a $s1% chance to remove|cFFFFFFFF Winning Streak!|r", ua = "Ваші закляття та здібності мають шанс активувати|cFFFFFFFF Переможну серію!|r, збільшуючи шкоду ваших «Морозного удару» та «Льодовикового наступу» на $1217897s1%, накопичуючись до $1217897u разів. «Морозний удар» та «Льодовиковий наступ» мають $s1% шанс зняти|cFFFFFFFF Переможну серію!|r" },
    { en = "Your spells and abilities have a chance to activate a|cFFFFFFFF Winning Streak!|r, increasing the damage of your Rising Sun Kick and Spinning Crane Kick by $1216182s1%, stacking up to $1216182u times. Rising Sun Kick and Spinning Crane Kick have a $s1% chance to remove|cFFFFFFFF Winning Streak!|r", ua = "Ваші закляття та здібності мають шанс активувати|cFFFFFFFF Переможну серію!|r, що збільшує шкоду ваших «Удару висхідного сонця» та «Обертового удару журавля» на $1216182s1%, накопичуючись до $1216182u разів. «Удар висхідного сонця» та «Обертовий удар журавля» мають $s1% шанс зняти|cFFFFFFFF Переможну серію!|r" },
    { en = "Your spells and abilities have a chance to cause your target to erupt in a blinding light dealing $345667s1 Arcane damage or healing an ally for $345668s1 health.", ua = "Ваші закляття та здібності мають шанс змусити вашу ціль спалахнути сліпучим світлом, що завдає $345667s1 арканної шкоди або зцілює союзника на $345668s1 здоров'я." },
    { en = "Your spells and abilities have a chance to create a floating orb of Fire Pollen nearby. Stepping into the orb will gather it, increasing your highest secondary stat by $451699s5 for $451699d. Up to 2 allies who step near you during this time will also receive $451980s4 of a random secondary stat for $451980d.", ua = "Ваші закляття і вміння мають шанс створити поблизу летючу кулю Вогняного пилку. Ступивши в кулю, ви зберете її, збільшивши вашу найвищу другорядну характеристику на $451699s5 протягом $451699d. До 2 союзників, які підійдуть до вас у цей час, також отримають $451980s4 випадкової другорядної характеристики протягом $451980d." },
    { en = "Your spells and abilities have a chance to hit a |cFFFFFFFFJackpot!|r reducing the cooldown of Combustion by $s1 sec. Casting Combustion has a $s3% chance to grant a |cFFFFFFFFJackpot!|r at $s2% increased effectiveness.", ua = "Ваші закляття та вміння мають шанс влучити в |cFFFFFFFFДжекпот!|r, зменшуючи час відновлення «Спопеління» на $s1 сек. Застосування «Спопеління» має $s3% шансу надати |cFFFFFFFFДжекпот!|r із $s2% збільшеної ефективності." },
    { en = "Your spells and abilities have a chance to hit a |cFFFFFFFFJackpot!|r that fires a Barbed Shot at $s1% effectiveness. Casting Bestial Wrath always hits a |cFFFFFFFFJackpot!|r", ua = "Ваші закляття та вміння мають шанс зірвати |cFFFFFFFFДжекпот!|r, що випускає Колючий Постріл з $s1% ефективністю. Творення Звіриного Гніву завжди зриває |cFFFFFFFFДжекпот!|r" },
    { en = "Your spells and abilities have a chance to hit a |cFFFFFFFFJackpot!|r that fires a Frostbolt Volley dealing ${$1216910s2*$s2} damage to your primary target and $1216910s2 damage to up to $s1 additional targets. Casting Icy Veins always hits a |cFFFFFFFFJackpot!|r", ua = "Ваші закляття та вміння мають шанс влучити в |cFFFFFFFFДжекпот!|r, що випускає «Залп крижаних стріл», завдаючи ${$1216910s2*$s2} шкоди вашій основній цілі та $1216910s2 шкоди до $s1 додаткових цілей. Творення «Крижаних вен» завжди влучає в |cFFFFFFFFДжекпот!|r" },
    { en = "Your spells and abilities have a chance to hit a |cFFFFFFFFJackpot!|r that fires a flurry of ${$1217731d/$1217731t1} Demonfire bolts at $s1% effectiveness. Casting Summon Infernal always hits a |cFFFFFFFFJackpot!|r", ua = "Ваші закляття та здібності мають шанс зірвати |cFFFFFFFFДжекпот!|r, що випускає шквал із ${$1217731d/$1217731t1} стріл Демонічного вогню з $s1% дієвістю. Прочитання Прикликання інфернала завжди зриває |cFFFFFFFFДжекпот!|r" },
    { en = "Your spells and abilities have a chance to hit a |cFFFFFFFFJackpot!|r that increases your auto shot damage by $1218033s1% and reduces the time between auto shots by ${$1218033s2/-1000}.1 sec for $1218033d. Casting Trueshot always hits a |cFFFFFFFFJackpot!|r", ua = "Ваші закляття та здібності мають шанс зірвати |cFFFFFFFFДжекпот!|r, що збільшує шкоду ваших автопострілів на $1218033s1% та зменшує час між автопострілами на ${$1218033s2/-1000}.1 с протягом $1218033d. Творіння «Влучного пострілу» завжди зриває |cFFFFFFFFДжекпот!|r" },
    { en = "Your spells and abilities have a chance to hit a |cFFFFFFFFJackpot!|r that increases your haste by $1219034s1% for $1219034d. Casting Summon Darkglare always hits a |cFFFFFFFFJackpot!|r", ua = "Ваші закляття і вміння мають шанс зірвати |cFFFFFFFFДжекпот!|r, що збільшує ваш Поспіх на $1219034s1% протягом $1219034d. Прочитання «Призвати Темнозора» завжди зриває |cFFFFFFFFДжекпот!|r" },
    { en = "Your spells and abilities have a chance to hit a |cFFFFFFFFJackpot!|r that summons a $?s192249[Storm][Fire] Elemental for ${$m1/1000}.1 sec. Casting Ascendance always hits a |cFFFFFFFFJackpot!|r", ua = "Ваші закляття та здібності мають шанс зірвати |cFFFFFFFFДжекпот!|r, що прикликає $?s192249[Штормового][Вогняного] елементаля на ${$m1/1000}.1 с. Читання «Піднесення» завжди зриває |cFFFFFFFFДжекпот!|r" },
    { en = "Your spells and abilities have a chance to hit a |cFFFFFFFFJackpot!|r that summons a Greater Dreadstalker at $1217617s1% effectiveness. Casting Summon Demonic Tyrant always hits a |cFFFFFFFFJackpot!|r", ua = "Ваші закляття та здібності мають шанс зірвати |cFFFFFFFFДжекпот!|r, що прикликає Величного жахоловця з $1217617s1% дієвістю. Прочитання Прикликання демонічного тирана завжди зриває |cFFFFFFFFДжекпот!|r" },
    { en = "Your spells and abilities have a chance to inflict Penance Brand on your target dealing ${$s1*6} Shadow damage over $345710d and healing you for the same amount.", ua = "Ваші закляття й здібності мають шанс накласти «Тавро покути» на вашу ціль, завдаючи ${$s1*6} шкоди Темрявою протягом $345710d і зцілюючи вас на таку саму величину." },
    { en = "Your spells and abilities have a chance to pelt your target with a magic snowball, causing enemies to take Frost damage or allies to receive healing.", ua = "Ваші закляття та здібності мають шанс жбурнути у вашу ціль чарівною сніжкою, від якої вороги зазнають шкоди Морозом, а союзники отримують зцілення." },
    { en = "Your spells and abilities have a chance to store away moments of time. Upon reaching $387141u stacks, release your stored time and gain a burst of Haste.", ua = "Ваші закляття та здібності мають шанс накопичувати миті часу. Досягнувши $387141u зарядів, ви вивільняєте накопичений час і отримуєте сплеск Поспіху." },
    { en = "Your spells and abilities have a low chance to summon a Fae Guardian to protect you for $345771d, increasing your $pri by $s2 while alive and periodically healing $345772s2 nearby allies for $s1 health.", ua = "Ваші закляття та здібності мають малий шанс прикликати «Фейну вартову», що захищає вас протягом $345771d, збільшуючи вашу $pri на $s2, поки жива, і періодично зцілюючи $345772s2 союзників поблизу на $s1 здоров'я." },
    { en = "Your spells and abilities have a small chance to hit a |cFFFFFFFFJackpot!|r granting you Clearcasting and $1216178s1% increased spell damage for $1216178d. Casting Touch of the Magi has a $s1% chance to hit a |cFFFFFFFFJackpot!|r", ua = "Ваші закляття та вміння мають невеликий шанс влучити в |cFFFFFFFFДжекпот!|r, що дає вам «Ясне чаклування» та збільшену на $1216178s1% шкоду заклять на $1216178d. Творення «Дотику магів» має $s1% шансу влучити в |cFFFFFFFFДжекпот!|r" },
    { en = "Your spells and attacks against Demons have a chance to deal an additional $228446s1 Fire damage.", ua = "Ваші закляття та атаки проти Демонів мають шанс завдати додатково $228446s1 шкоди Вогнем." },
    { en = "Your spells and attacks have a chance to increase your Critical Strike by $224151s1 for $224151d.", ua = "Ваші закляття та атаки мають шанс підвищити ваш Критичний удар на $224151s1 на $224151d." },
    { en = "Your spells and attacks have a chance to increase your Mastery by $224149s1 for $224149d.", ua = "Ваші закляття та атаки мають шанс підвищити вашу Майстерність на $224149s1 на $224149d." },
    { en = "Your spells and attacks have a chance to increase your Versatility by $228449s1 for $228449d.", ua = "Ваші закляття та атаки мають шанс збільшити вашу Універсальність на $228449s1 протягом $228449d." },
    { en = "Your spells generate $s1% less threat. In addition, Corruption, Immolate, Curse of Agony, and Siphon Life further generate $s2% less threat.", ua = "Ваші закляття генерують на $s1% менше загрози. Крім того, «Псування», «Спалення», «Прокляття агонії» та «Викачування життя» генерують ще на $s2% менше загрози." },
    { en = "Your spells have a $s1% chance to call down a Comet Storm on your target enemy. This effect cannot occur more than once every $proccooldown sec.", ua = "Ваші закляття мають $s1% шанс закликати «Кометну бурю» на ворога-ціль. Цей ефект може спрацьовувати не частіше ніж раз на $proccooldown с." },
    { en = "Your spells have a chance to grant you Umbral Shift, reducing all Shadow damage taken$?a253819[ by up to $w1][] for $253826d.", ua = "Ваші закляття мають шанс дати вам Тіньовий зсув, що зменшує всю отриману тіньову шкоду$?a253819[ до $w1][] на $253826d." },
    { en = "Your spells have a chance to increase your Haste by $224147s1 for $224147d.", ua = "Ваші закляття мають шанс збільшити ваш Поспіх на $224147s1 протягом $224147d." },
    { en = "Your spells have an increased chance to trigger Brain Freeze or Pyroblast!.  In addition, Arcane Power decreases the cost of your damaging spells by 10% instead of increasing their cost.", ua = "Ваші закляття мають підвищений шанс спрацювати «Крижаний розум» або «Піровибух!».  Крім того, «Арканна сила» зменшує вартість ваших шкодочинних заклять на 10% замість того, щоб її підвищувати." },
    { en = "Ysera's Gift now applies Dreamer to the target, healing them for $253432o1 over $253432d.", ua = "Дар Ісери тепер накладає Сновидця на ціль, зцілюючи її на $253432o1 протягом $253432d." },
    { en = "|cFFFFFFFFLuck of the Draw!|r has ${$s1/1000} sec increased duration.\n\nWhile |cFFFFFFFFLuck of the Draw!|r is active, Death Strike costs ${-$1218601S5/10} less Runic Power and can strike up to $1218601m4 additional nearby $Lenemy:enemies;.", ua = "|cFFFFFFFFФортуна!|r має на ${$s1/1000} сек. більшу тривалість.\n\nПоки |cFFFFFFFFФортуна!|r активна, Смертельний удар коштує на ${-$1218601S5/10} менше Рунічної сили та може вразити до $1218601m4 додаткових $Lворога:ворогів; поблизу." },
    { en = "|cFFFFFFFFWinning Streak!|r causes Frost Strike and Glacial Advance to have a $s2% chance to cast Frostscythe per stack at $s1% effectiveness. Losing |cFFFFFFFFWinning Streak!|r sends you into a Murderous Frenzy, casting Frostscythe at $s3% effectiveness and gaining ${$1222698s1*$mastery}% Mastery for $1222698d. Additionally, Frostscythe deals $s4% more damage to the first target struck.", ua = "|cFFFFFFFFСмуга перемог!|r робить так, що «Крижаний удар» і «Льодовиковий наступ» мають $s2% шансу застосувати «Морозну косу» за стос з ефективністю $s1%. Втрата |cFFFFFFFFСмуги перемог!|r кидає вас у «Смертоносне шаленство», застосовуючи «Морозну косу» з ефективністю $s3% і даючи ${$1222698s1*$mastery}% Майстерності протягом $1222698d. Крім того, «Морозна коса» завдає на $s4% більше шкоди першій враженій цілі." },
    { en = "|cFFFFFFFFWinning Streak!|r persists for $1220706d after being removed by Blade Dance or Chaos Strike.\n\nEntering demon form sacrifices all |cFFFFFFFFWinning Streak!|r stacks to gain $1217055s1% critical strike chance per stack consumed. Lasts $1217055d.", ua = "|cFFFFFFFFПереможна серія!|r зберігається протягом $1220706d після зняття Танцем клинків або Ударом хаосу.\n\nПеретворення на демонічну форму жертвує всіма зарядами |cFFFFFFFFПереможної серії!|r, надаючи $1217055s1% шансу критичного удару за кожен спожитий заряд. Триває $1217055d." },
}
